const initialWorld=()=>({currentMapId:'0,0',player:{x:1,y:1},mapRuntime:{},moving:false,moveInterval:null,currentEncounterMobIds:null,pendingReturn:null});
const makePersistence=(storage,state)=>Persistence.createSaveSystem({storage,mapDatabase:testMaps,itemDb:testItems,createInitialPlayerState:Rules.createPlayerState,createInitialWorldState:initialWorld,stateProvider:()=>state||({player:Rules.createPlayerState(),world:initialWorld(),progression:{quests:{},currency:{},flags:{}}})});
