const makeQuestSystem=(progression={},rewardSink=()=>{})=>QuestApi.createQuestSystem({questDb:QuestData,progression,rewardSink});
const makeQuestChainSystem=(needsSecond=false,rewardSink=()=>{})=>{const progression={primeira_batalha:{state:'COMPLETED',progress:{kill_javali_1:1},seenEvents:{},rewardClaimed:true}};if(needsSecond)progression.rastros_na_mata={state:'COMPLETED',progress:{kill_javali_2:2,collect_couro_javali:2},seenEvents:{},rewardClaimed:true};return QuestApi.createQuestSystem({questDb:QuestData,progression,rewardSink});};
const makeNpcEngine=(questSystem=makeQuestSystem(),player={x:1,y:1,hp:10,maxHp:100},onChanged=()=>{})=>NpcApi.createNpcSystem({npcDb:NpcData,questSystem,worldProvider:()=>({currentMapId:'0,0',player}),playerProvider:()=>player,onChanged});
const makeFimbriaRuntimeFixture=({storage=null}={})=>{
  const player=Rules.createPlayerState(),world={currentMapId:'MAP_01',player:{x:6,y:5},mapRuntime:{},moving:false,moveInterval:null,currentEncounterMobIds:null,pendingReturn:null},progression={quests:{},currency:{},flags:{}};
  const questDb=FimbriaQuestAdapter.createQuestDatabase(QuestData,Fimbria.quests),npcDb=FimbriaQuestAdapter.createNpcDatabase(NpcData,Fimbria.quests,Fimbria.aliases);
  const questSystem=QuestApi.createQuestSystem({questDb,progression:progression.quests,autoComplete:false,flagProvider:flag=>progression.flags[flag]===true,inventoryProvider:()=>player,flagSink:flag=>worldState.setFlag(flag,true),eventAdapter:event=>FimbriaRuntime.adaptQuestEvent(event),rewardSink:reward=>Rules.addLoot(player,(reward.items||[]).map(item=>({id:item.itemId,qty:item.amount}))) });
  const worldState=WorldApi.createWorldState({progressionProvider:()=>progression,questSystem});
  const inspections=FimbriaInspections.createInspectionSystem({runtime:FimbriaRuntime,worldState,questSystem,itemSink:({itemId,amount})=>Rules.addLoot(player,[{id:itemId,qty:amount}])});
  const npcs=NpcApi.createNpcSystem({npcDb,questSystem,worldProvider:()=>world,playerProvider:()=>player,mapIdResolver:FimbriaRuntime.normalizeMapId});
  const narrative=NarrativeApi.createNarrativeAdapter({questSystem,worldState,inventoryProvider:()=>player,itemSink:({itemId,amount})=>Rules.addLoot(player,[{id:itemId,qty:amount}])});
  let visitSequence=0;
  const visit=(exitId)=>{const result=FimbriaRuntime.prepareTransition({mapId:world.currentMapId,exitId,flagProvider:flag=>worldState.hasFlag(flag)});if(!result.ok)return result;world.currentMapId=result.targetMapId;world.player={...result.targetPosition};FimbriaQuestAdapter.acceptMapAssignedQuests(world.currentMapId,Fimbria.maps,questSystem);questSystem.recordEvent({type:'MAP_VISITED',mapId:world.currentMapId,eventId:`visit:${++visitSequence}:${world.currentMapId}`});return result;};
  const talk=(npcId)=>{const npc=npcs.getDefinition(npcId);world.player={x:npc.position.x,y:npc.position.y};return npcs.interact(npcId);};
  const gates=GateApi.createGateEngine({flagProvider:flag=>worldState.hasFlag(flag),questStateProvider:id=>questSystem.getQuestState(id)});
  const fixture={player,world,progression,questDb,npcDb,questSystem,worldState,inspections,npcs,narrative,visit,talk,gates};
  if(storage)fixture.save=Persistence.createSaveSystem({storage,mapDatabase:FimbriaRuntime.mapDatabase,itemDb:ItemData,createInitialPlayerState:Rules.createPlayerState,createInitialWorldState:()=>({currentMapId:'MAP_01',player:FimbriaRuntime.resolveSpawn('MAP_01'),mapRuntime:{}}),normalizeMapId:FimbriaRuntime.normalizeMapId,stateProvider:()=>fixture});
  return fixture;
};
