test('QUEST_DB is valid',()=>{Object.values(QuestData).forEach(q=>{assert.equal(typeof q.id,'string');assert(q.id.length>0);assert(q.objectives.length>0);q.objectives.forEach(o=>assert(['KILL','COLLECT','EXPLORE','TALK','BOSS'].includes(o.type)));});});
test('QUEST_DB IDs are unique',()=>{const ids=Object.values(QuestData).map(q=>q.id);assert.equal(new Set(ids).size,ids.length);});
test('Quest starts available',()=>assert.equal(makeQuestSystem().getQuestState('primeira_batalha'),QuestApi.QUEST_STATES.AVAILABLE));
test('Quest can be locked by prerequisite',()=>{const db={a:{id:'a',prerequisites:['missing'],objectives:[{id:'o',type:'KILL',target:'x',amount:1}],rewards:{}}};const q=QuestApi.createQuestSystem({questDb:db,progression:{}});assert.equal(q.getQuestState('a'),QuestApi.QUEST_STATES.LOCKED);});
test('Accept quest',()=>{const q=makeQuestSystem();assert(q.acceptQuest('primeira_batalha'));assert.equal(q.getQuestState('primeira_batalha'),'ACTIVE');});
test('Cannot accept quest twice',()=>{const q=makeQuestSystem();assert(q.acceptQuest('primeira_batalha'));assert.equal(q.acceptQuest('primeira_batalha'),false);});
test('KILL increments matching target',()=>{const q=makeQuestSystem();q.acceptQuest('primeira_batalha');assert(q.recordEvent({type:'MOB_KILLED',mobType:'javali',eventId:'k1'}));assert.equal(q.getObjectiveViews('primeira_batalha')[0].current,1);});
test('KILL ignores wrong mob',()=>{const q=makeQuestSystem();q.acceptQuest('primeira_batalha');q.recordEvent({type:'MOB_KILLED',mobType:'cogumelo',eventId:'k1'});assert.equal(q.getObjectiveViews('primeira_batalha')[0].current,0);});
test('KILL clamps at requirement',()=>{const q=makeQuestChainSystem();q.acceptQuest('rastros_na_mata');q.recordEvent({type:'MOB_KILLED',mobType:'javali',eventId:'k1'});q.recordEvent({type:'MOB_KILLED',mobType:'javali',eventId:'k2'});q.recordEvent({type:'MOB_KILLED',mobType:'javali',eventId:'k3'});assert.equal(q.getObjectiveViews('rastros_na_mata')[0].current,2);});
test('COLLECT increments matching item',()=>{const q=makeQuestChainSystem();q.acceptQuest('rastros_na_mata');q.recordEvent({type:'ITEM_ACQUIRED',itemId:'couro_javali',amount:1,eventId:'i1'});assert.equal(q.getObjectiveViews('rastros_na_mata')[1].current,1);});
test('COLLECT ignores wrong item',()=>{const q=makeQuestChainSystem();q.acceptQuest('rastros_na_mata');q.recordEvent({type:'ITEM_ACQUIRED',itemId:'dente_afiado',amount:3,eventId:'i1'});assert.equal(q.getObjectiveViews('rastros_na_mata')[1].current,0);});
test('EXPLORE completes correctly',()=>{const q=makeQuestChainSystem(true);q.acceptQuest('reconhecimento_da_floresta');q.recordEvent({type:'MAP_VISITED',mapId:'1,0',eventId:'map1'});q.recordEvent({type:'NPC_TALKED',npcId:'exploradora_lia',eventId:'talk1'});assert.equal(q.getQuestState('reconhecimento_da_floresta'),'COMPLETED');});
test('TALK is supported by engine',()=>{const db={q:{id:'q',prerequisites:[],objectives:[{id:'t',type:'TALK',target:'guide',amount:1}],rewards:{}}};const q=QuestApi.createQuestSystem({questDb:db,progression:{}});q.acceptQuest('q');q.recordEvent({type:'NPC_TALKED',npcId:'guide',eventId:'talk1'});assert(q.isComplete('q'));});
test('Multiple objectives are tracked',()=>{const q=makeQuestChainSystem();q.acceptQuest('rastros_na_mata');q.recordEvent({type:'MOB_KILLED',mobType:'javali',eventId:'k1'});q.recordEvent({type:'ITEM_ACQUIRED',itemId:'couro_javali',amount:2,eventId:'i1'});assert.equal(q.getObjectiveViews('rastros_na_mata')[0].current,1);assert.equal(q.getObjectiveViews('rastros_na_mata')[1].current,2);});
test('Quest waits for all objectives',()=>{const q=makeQuestChainSystem();q.acceptQuest('rastros_na_mata');q.recordEvent({type:'MOB_KILLED',mobType:'javali',eventId:'k1'});q.recordEvent({type:'MOB_KILLED',mobType:'javali',eventId:'k2'});assert.equal(q.getQuestState('rastros_na_mata'),'ACTIVE');});
test('Quest completion changes state',()=>{const q=makeQuestSystem();q.acceptQuest('primeira_batalha');q.recordEvent({type:'MOB_KILLED',mobType:'javali',eventId:'k1'});assert.equal(q.getQuestState('primeira_batalha'),'COMPLETED');});
test('Quest grants XP reward',()=>{let xp=0;const q=makeQuestSystem({},r=>{xp+=r.xp||0;});q.acceptQuest('primeira_batalha');q.recordEvent({type:'MOB_KILLED',mobType:'javali',eventId:'k1'});assert.equal(xp,35);});
test('Quest grants item reward',()=>{let items=[];const q=makeQuestChainSystem(false,r=>{items=items.concat(r.items||[]);});q.acceptQuest('rastros_na_mata');q.recordEvent({type:'MOB_KILLED',mobType:'javali',eventId:'k1'});q.recordEvent({type:'MOB_KILLED',mobType:'javali',eventId:'k2'});q.recordEvent({type:'ITEM_ACQUIRED',itemId:'couro_javali',amount:2,eventId:'i1'});assert.equal(items[0].itemId,'dente_afiado');});
test('Quest XP can level up through existing rules',()=>{const p=Rules.createPlayerState();p.xp=90;const db={q:{id:'q',prerequisites:[],objectives:[{id:'o',type:'KILL',target:'x',amount:1}],rewards:{xp:35}}};const q=QuestApi.createQuestSystem({questDb:db,progression:{},rewardSink:r=>Rules.grantXp(p,r.xp)});q.acceptQuest('q');q.recordEvent({type:'MOB_KILLED',mobType:'x',eventId:'k'});assert.equal(p.level,2);});
test('Quest reward is not duplicated',()=>{let count=0;const q=makeQuestSystem({},()=>count++);q.acceptQuest('primeira_batalha');q.recordEvent({type:'MOB_KILLED',mobType:'javali',eventId:'k1'});assert.equal(q.completeQuest('primeira_batalha'),false);assert.equal(count,1);});
