test('Quest progress persists',()=>{const state=baseSnapshot(),storage=new Persistence.MemoryStorageAdapter(),q=makeQuestSystem();q.acceptQuest('primeira_batalha');q.recordEvent({type:'MOB_KILLED',mobType:'javali',eventId:'k1'});state.progression.quests=q.progression;const s=makePersistence(storage,state);s.saveNow();assert.equal(makePersistence(storage).load().progression.quests.primeira_batalha.progress.kill_javali_1,1);});
test('Completed quest persists',()=>{const state=baseSnapshot(),storage=new Persistence.MemoryStorageAdapter(),q=makeQuestSystem();q.acceptQuest('primeira_batalha');q.recordEvent({type:'MOB_KILLED',mobType:'javali',eventId:'k1'});state.progression.quests=q.progression;const s=makePersistence(storage,state);s.saveNow();assert.equal(makePersistence(storage).load().progression.quests.primeira_batalha.state,'COMPLETED');});
test('Reload does not duplicate reward',()=>{let rewards=0;const progression={primeira_batalha:{state:'COMPLETED',progress:{kill_javali_1:1},seenEvents:{k1:true},rewardClaimed:true}};const q=makeQuestSystem(progression,()=>rewards++);assert.equal(q.completeQuest('primeira_batalha'),false);assert.equal(rewards,0);});
test('MAP_VISITED does not overcount',()=>{const q=makeQuestChainSystem(true);q.acceptQuest('reconhecimento_da_floresta');q.recordEvent({type:'MAP_VISITED',mapId:'1,0',eventId:'m1'});q.recordEvent({type:'MAP_VISITED',mapId:'1,0',eventId:'m2'});assert.equal(q.getObjectiveViews('reconhecimento_da_floresta')[0].current,1);});
test('Duplicate MOB_KILLED event is ignored',()=>{const q=makeQuestChainSystem();q.acceptQuest('rastros_na_mata');q.recordEvent({type:'MOB_KILLED',mobType:'javali',eventId:'same'});q.recordEvent({type:'MOB_KILLED',mobType:'javali',eventId:'same'});assert.equal(q.getObjectiveViews('rastros_na_mata')[0].current,1);});
