test('Mob creation',()=>{const m=Rules.createMob({id:'mob-1',type:'boar'},{name:'Boar',hp:5,maxHp:5,pa:2,maxPa:2,pm:1,maxPm:1},{x:2,y:3});assert.equal(m.combatantId,'mob-1');assert.equal(m.x,2);});
test('Player creation',()=>assert.equal(Rules.createPlayerState().playerId,'player'));
test('Turn order keeps combatant IDs',()=>{const ids=Rules.initiative([{id:'player',side:'player'},{id:'mob-9',side:'mob',mobType:'boar'}],20,{boar:{agilidade:1}},rng([.5,.5]));assert.deepEqual(ids,['player','mob-9']);});
test('Turn order skips dead',()=>{const byId=id=>({a:{hp:0},b:{hp:1},c:{hp:1}}[id]);assert.equal(Rules.nextAliveIndex(['a','b','c'],0,byId),1);});
test('Smoke: create, fight, reward, return state',()=>{const p=Rules.createPlayerState(),m=Rules.createMob({id:'m1',type:'boar'},{name:'Boar',hp:10,maxHp:10,pa:1,maxPa:1,pm:1,maxPm:1},{x:1,y:1});assert(Rules.spendAp({hp:1,pa:4},3));Rules.applyDamage(m,10);assert.equal(m.hp,0);Rules.addLoot(p,[{id:'hide',qty:1}]);Rules.grantXp(p,45);const state='OVERWORLD';assert.equal(state,'OVERWORLD');assert.equal(p.inventory.hide,1);});
test('Smoke: save, rebuild, combat interruption, safe return',()=>{const state=baseSnapshot();state.player.level=3;state.player.inventory.hide=2;state.world.player={x:2,y:2};const storage=new Persistence.MemoryStorageAdapter(),writer=makePersistence(storage,state);writer.saveNow();const rebuilt=makePersistence(storage).load();assert.equal(rebuilt.player.level,3);assert.equal(rebuilt.player.inventory.hide,2);const session=makePersistence(storage,{...rebuilt,combat:{turnIndex:1}});session.captureSafeState(rebuilt.world);const interrupted=session.saveNow();assert.equal(interrupted.combat,undefined);assert.deepEqual(makePersistence(storage).load().world.player,{x:2,y:2});});
test('Smoke: quest combat, reward, save, reload',()=>{const state=baseSnapshot(),storage=new Persistence.MemoryStorageAdapter();let rewardCount=0;const player=state.player,q=QuestApi.createQuestSystem({questDb:QuestData,progression:{primeira_batalha:{state:'COMPLETED',progress:{kill_javali_1:1},seenEvents:{},rewardClaimed:true}},autoComplete:false,rewardSink:rewards=>{rewardCount++;Rules.grantXp(player,rewards.xp||0);Rules.addLoot(player,(rewards.items||[]).map(i=>({id:i.itemId,qty:i.amount})));}});q.acceptQuest('rastros_na_mata');q.recordEvent({type:'MOB_KILLED',mobType:'javali',eventId:'combat-1:mob-1'});q.recordEvent({type:'MOB_KILLED',mobType:'javali',eventId:'combat-1:mob-2'});q.recordEvent({type:'ITEM_ACQUIRED',itemId:'couro_javali',amount:2,eventId:'loot-1'});assert(q.isComplete('rastros_na_mata'));assert.equal(q.getQuestState('rastros_na_mata'),'ACTIVE');assert(q.completeQuest('rastros_na_mata'));state.progression.quests=q.progression;makePersistence(storage,state).saveNow();const rebuilt=makePersistence(storage).load();assert.equal(rebuilt.progression.quests.rastros_na_mata.state,'COMPLETED');const reloaded=makeQuestSystem(rebuilt.progression.quests,()=>rewardCount++);assert.equal(reloaded.completeQuest('rastros_na_mata'),false);assert.equal(rewardCount,1);});

test('NPC_DB has valid definitions',()=>{Object.values(NpcData).forEach(n=>{assert(n.id&&n.name&&n.role);assert.equal(n.mapId,'0,0');assert(Number.isInteger(n.position.x)&&Number.isInteger(n.position.y));assert(n.dialogue);});});
test('NPC IDs are unique',()=>{const ids=Object.values(NpcData).map(n=>n.id);assert.equal(new Set(ids).size,ids.length);});
test('NPC roles are supported',()=>{Object.values(NpcData).forEach(n=>assert(Object.values(NpcApi.ROLES).includes(n.role)));});
