test('NPC TALK event is deduplicated by event id',()=>{const q=QuestApi.createQuestSystem({questDb:{q:{id:'q',prerequisites:[],objectives:[{id:'talk',type:'TALK',target:'guarda_mira',amount:2}],rewards:{}}},progression:{}});q.acceptQuest('q');const e=makeNpcEngine(q);e.interact('guarda_mira');e.interact('guarda_mira');assert.equal(q.getObjectiveViews('q')[0].current,2);});
