test('NPC delivery completes quest and claims reward once',()=>{let rewards=0;const q=QuestApi.createQuestSystem({questDb:QuestData,progression:{},autoComplete:false,rewardSink:()=>rewards++});const e=makeNpcEngine(q);e.execute('guarda_mira',{id:'accept_quest',questId:'primeira_batalha'});q.recordEvent({type:'MOB_KILLED',mobType:'javali',eventId:'k'});assert(e.execute('guarda_mira',{id:'deliver_quest',questId:'primeira_batalha'}).ok);assert.equal(q.getQuestState('primeira_batalha'),'COMPLETED');assert.equal(rewards,1);assert.equal(e.execute('guarda_mira',{id:'deliver_quest',questId:'primeira_batalha'}).ok,false);assert.equal(rewards,1);});
