test('Smoke: village quest chain, TALK, reward and reload',()=>{const state=baseSnapshot(),storage=new Persistence.MemoryStorageAdapter(),player={x:1,y:1,hp:100,maxHp:100};let rewards=0;const q=QuestApi.createQuestSystem({questDb:QuestData,progression:{},autoComplete:false,rewardSink:()=>rewards++});const e=makeNpcEngine(q,player);assert(e.execute('guarda_mira',{id:'accept_quest',questId:'primeira_batalha'}).ok);q.recordEvent({type:'MOB_KILLED',mobType:'javali',eventId:'smoke-q1'});assert(e.execute('guarda_mira',{id:'deliver_quest',questId:'primeira_batalha'}).ok);assert(e.execute('guarda_mira',{id:'accept_quest',questId:'rastros_na_mata'}).ok);q.recordEvent({type:'MOB_KILLED',mobType:'javali',eventId:'smoke-q2a'});q.recordEvent({type:'MOB_KILLED',mobType:'javali',eventId:'smoke-q2b'});q.recordEvent({type:'ITEM_ACQUIRED',itemId:'couro_javali',amount:2,eventId:'smoke-loot'});assert(e.execute('guarda_mira',{id:'deliver_quest',questId:'rastros_na_mata'}).ok);assert(e.execute('guarda_mira',{id:'accept_quest',questId:'reconhecimento_da_floresta'}).ok);q.recordEvent({type:'MAP_VISITED',mapId:'1,0'});player.x=6;player.y=1;assert(e.interact('exploradora_lia').ok);player.x=1;player.y=1;assert(e.execute('guarda_mira',{id:'deliver_quest',questId:'reconhecimento_da_floresta'}).ok);assert.equal(rewards,3);state.progression.quests=q.progression;makePersistence(storage,state).saveNow();const loaded=makePersistence(storage).load();assert.equal(loaded.progression.quests.reconhecimento_da_floresta.state,'COMPLETED');assert.equal(loaded.progression.quests.rastros_na_mata.state,'COMPLETED');});

test('Player starts with valid persistent HP',()=>{const p=Rules.createPlayerState();assert.equal(p.hp,100);assert.equal(p.maxHp,100);assert(p.hp>0&&p.hp<=p.maxHp);});
