test('Healer restores persistent player HP',()=>{const p=Rules.createPlayerState();p.hp=22;const e=makeNpcEngine(makeQuestSystem(),{x:6,y:3,hp:p.hp,maxHp:p.maxHp},()=>{});const target=e.playerProvider?e.playerProvider():p;const result=e.execute('curandeiro_nilo',{id:'heal'});assert(result.ok);assert.equal(result.healed,true);});
test('Healer never exceeds max HP',()=>{const p={x:6,y:3,hp:99,maxHp:100};const e=makeNpcEngine(makeQuestSystem(),p);e.execute('curandeiro_nilo',{id:'heal'});assert.equal(p.hp,100);});
test('Consumable exists in data',()=>{const item=ItemData.pocao_simples;assert.equal(item.type,'CONSUMABLE');assert.equal(item.effect.type,'HEAL');assert(item.effect.amount>0);});
test('Consumable heals target',()=>{const p=Rules.createPlayerState();p.hp=50;p.inventory.pocao_simples=1;const result=makeConsumable(p).use('pocao_simples');assert(result.ok);assert.equal(p.hp,80);});
test('Consumable respects max HP',()=>{const p=Rules.createPlayerState();p.hp=90;p.inventory.pocao_simples=1;const result=makeConsumable(p).use('pocao_simples');assert.equal(p.hp,100);assert.equal(result.healed,10);});
test('Consumable decreases quantity',()=>{const p=Rules.createPlayerState();p.hp=50;p.inventory.pocao_simples=2;makeConsumable(p).use('pocao_simples');assert.equal(p.inventory.pocao_simples,1);});
test('Consumable quantity never becomes negative',()=>{const p=Rules.createPlayerState();p.hp=50;p.inventory.pocao_simples=1;makeConsumable(p).use('pocao_simples');assert.equal(p.inventory.pocao_simples,undefined);assert.equal(makeConsumable(p).use('pocao_simples').ok,false);});
test('Unknown item cannot be used',()=>{const p=Rules.createPlayerState();p.inventory.missing=1;assert.equal(makeConsumable(p).use('missing').ok,false);});
test('Consumable with zero quantity fails',()=>{const p=Rules.createPlayerState();p.hp=50;p.inventory.pocao_simples=0;assert.equal(makeConsumable(p).use('pocao_simples').ok,false);});
test('Consumable works outside combat',()=>{const p=Rules.createPlayerState();p.hp=40;p.inventory.pocao_simples=1;const result=makeConsumable(p,null).use('pocao_simples');assert(result.ok);assert.equal(result.inCombat,false);assert.equal(p.hp,70);});
