test('Combat consumable costs configured PA',()=>{const p=Rules.createPlayerState();p.hp=40;p.inventory.pocao_simples=1;const combat={player:{hp:40,maxHp:100,pa:6}};const result=makeConsumable(p,combat).use('pocao_simples');assert.equal(result.paCost,2);assert.equal(combat.player.pa,4);});
test('Insufficient PA prevents consumable',()=>{const p=Rules.createPlayerState();p.hp=40;p.inventory.pocao_simples=1;const combat={player:{hp:40,maxHp:100,pa:1}};const result=makeConsumable(p,combat).use('pocao_simples');assert.equal(result.ok,false);assert.equal(result.reason,'PA');assert.equal(p.inventory.pocao_simples,1);});
test('Combat consumable waits for player turn',()=>{const p=Rules.createPlayerState();p.hp=40;p.inventory.pocao_simples=1;const combat={player:{hp:40,maxHp:100,pa:6},canUse:false};const result=makeConsumable(p,combat).use('pocao_simples');assert.equal(result.ok,false);assert.equal(result.reason,'TURN');assert.equal(p.inventory.pocao_simples,1);});
