test('Full HP potion is rejected without consuming item',()=>{const p=Rules.createPlayerState();p.inventory.pocao_simples=1;const result=makeConsumable(p).use('pocao_simples');assert.equal(result.ok,false);assert.equal(result.reason,'FULL');assert.equal(p.inventory.pocao_simples,1);});
test('Respawn preserves current map data and uses village map',()=>{const map=MapData['0,0'];assert.equal(map.name,'Vila de Entrada');assert(map.respawnPoint.x>=0&&map.respawnPoint.y>=0);});

// Mission 6B: the effect engine is intentionally tested without canvas/DOM.
const combatRng=(roll=0.99)=>({random:()=>roll,int:(min,max)=>min});
const makeCombatState=(units,boardSize=6)=>({board:Array.from({length:boardSize},()=>Array(boardSize).fill('empty')),combatants:units,eventSequence:0});
const makeUnit=(id,side,x,y,overrides={})=>({id,side,name:id,x,y,hp:100,maxHp:100,pa:6,maxPa:6,pm:4,maxPm:4,cooldowns:{},effects:[],resistances:{PHYSICAL:0,MAGICAL:0},combatStats:{},...overrides});
const makeCombatEngine=(roll=.99)=>CombatEffects.createCombatEngine({rules:Rules,rng:combatRng(roll)});
const eventTypes=events=>events.map(event=>event.type);

test('Combat V2 ability data has effect declarations',()=>{Object.values(Abilities).forEach(ability=>{assert.equal(ability.id.length>0,true);assert(Array.isArray(ability.effects)&&ability.effects.length>0);assert(ability.range);assert(ability.targeting);});});
test('Combat V2 physical damage applies resistance',()=>{const player=makeUnit('p','player',1,1),mob=makeUnit('m','mob',2,1,{resistances:{PHYSICAL:.2,MAGICAL:0}}),state=makeCombatState([player,mob]);const result=makeCombatEngine().cast(state,{actorId:'p',ability:{id:'hit',apCost:2,range:{min:1,max:1},targeting:{targetType:'ENEMY'},effects:[{type:'DAMAGE',target:'TARGET',damageType:'PHYSICAL',amount:50}]},target:{x:2,y:1}});assert(result.ok);assert.equal(player.pa,4);assert.equal(mob.hp,60);assert.equal(result.events.find(e=>e.type==='DAMAGE_APPLIED').resistance,.2);});
test('Combat V2 magical damage uses intelligence and resistance',()=>{const player=makeUnit('p','player',1,1,{combatStats:{inteligencia:100}}),mob=makeUnit('m','mob',2,1,{resistances:{PHYSICAL:0,MAGICAL:.1}}),state=makeCombatState([player,mob]);makeCombatEngine().cast(state,{actorId:'p',ability:{id:'spell',apCost:0,range:{min:1,max:1},targeting:{targetType:'ENEMY'},effects:[{type:'DAMAGE',target:'TARGET',damageType:'MAGICAL',amount:10}]},target:{x:2,y:1}});assert.equal(mob.hp,82);});
test('Combat V2 clamps resistance at supported bounds',()=>{assert.equal(Rules.sanitizeResistance(-1),-.5);assert.equal(Rules.sanitizeResistance(1),.85);const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',2,1,{resistances:{PHYSICAL:.99,MAGICAL:0}}),state=makeCombatState([p,m]);makeCombatEngine().cast(state,{actorId:'p',ability:{id:'hit',apCost:0,range:{min:1,max:1},targeting:{targetType:'ENEMY'},effects:[{type:'DAMAGE',target:'TARGET',amount:100}]},target:{x:2,y:1}});assert.equal(m.hp,85);});
test('Combat V2 rejects invalid casts without PA or events',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',4,1),state=makeCombatState([p,m]);const result=makeCombatEngine().cast(state,{actorId:'p',ability:Abilities.golpe,target:{x:4,y:1}});assert.equal(result.ok,false);assert.equal(result.reason,'RANGE');assert.equal(p.pa,6);assert.equal(result.events.length,0);});
test('Combat V2 cooldown blocks and expires on the owner start turn',()=>{const p=makeUnit('p','player',1,1,{pa:10,maxPa:10}),m=makeUnit('m','mob',2,1),state=makeCombatState([p,m]),engine=makeCombatEngine();assert(engine.cast(state,{actorId:'p',ability:Abilities.golpe,target:{x:2,y:1}}).ok);assert.equal(p.cooldowns.golpe,2);assert.equal(engine.cast(state,{actorId:'p',ability:Abilities.golpe,target:{x:2,y:1}}).reason,'COOLDOWN');engine.startTurn(state,'p');assert.equal(p.cooldowns.golpe,1);engine.startTurn(state,'p');assert.equal(p.cooldowns.golpe,undefined);});
test('Combat V2 cross resolves only enemy units in its area',()=>{const p=makeUnit('p','player',1,1),enemy=makeUnit('enemy','mob',3,1),ally=makeUnit('ally','player',3,2),outside=makeUnit('outside','mob',5,2),state=makeCombatState([p,enemy,ally,outside]);const result=makeCombatEngine().cast(state,{actorId:'p',ability:Abilities.cruz,target:{x:3,y:1}});assert(result.ok);assert(enemy.hp<100);assert.equal(ally.hp,100);assert.equal(outside.hp,100);assert.equal(enemy.effects[0].statusId,'VULNERABLE');});
test('Combat V2 refreshes a same-source status instead of stacking it',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',2,1),state=makeCombatState([p,m]),engine=makeCombatEngine();const ability={id:'mark',apCost:0,range:{min:1,max:1},targeting:{targetType:'ENEMY'},effects:[{type:'STATUS',target:'TARGET',statusId:'VULNERABLE',duration:2,modifiers:{physicalResistance:-.1}}]};engine.cast(state,{actorId:'p',ability,target:{x:2,y:1}});engine.endTurn(state,'m');const second=engine.cast(state,{actorId:'p',ability,target:{x:2,y:1}});assert.equal(m.effects.length,1);assert.equal(m.effects[0].duration,2);assert.equal(second.events.find(e=>e.type==='STATUS_APPLIED').refreshed,true);});
test('Combat V2 vulnerability changes subsequent resistance',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',2,1,{resistances:{PHYSICAL:.1,MAGICAL:0}}),state=makeCombatState([p,m]),engine=makeCombatEngine();const debuff={id:'debuff',apCost:0,range:{min:1,max:1},targeting:{targetType:'ENEMY'},effects:[{type:'DEBUFF',target:'TARGET',statusId:'VULNERABLE',duration:2,modifiers:{physicalResistance:-.15}}]};engine.cast(state,{actorId:'p',ability:debuff,target:{x:2,y:1}});engine.cast(state,{actorId:'p',ability:{id:'hit',apCost:0,range:{min:1,max:1},targeting:{targetType:'ENEMY'},effects:[{type:'DAMAGE',target:'TARGET',amount:100}]},target:{x:2,y:1}});assert.equal(m.hp,0);});
test('Combat V2 poison ticks at start and expires on affected end turns',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',3,1),state=makeCombatState([p,m]),engine=makeCombatEngine();assert(engine.cast(state,{actorId:'p',ability:Abilities.lanca,target:{x:3,y:1}}).ok);const hpAfterCast=m.hp;const first=engine.startTurn(state,'m');assert.equal(m.hp,hpAfterCast-8);assert(eventTypes(first.events).includes('DAMAGE_APPLIED'));engine.endTurn(state,'m');const second=engine.startTurn(state,'m');assert.equal(m.hp,hpAfterCast-16);engine.endTurn(state,'m');assert.equal(m.effects.length,0);assert(eventTypes(second.events).includes('DAMAGE_APPLIED'));});
test('Combat V2 fortified defense applies then expires deterministically',()=>{const p=makeUnit('p','player',1,1),state=makeCombatState([p]),engine=makeCombatEngine();assert(engine.cast(state,{actorId:'p',ability:Abilities.fortificar,target:{x:1,y:1}}).ok);assert.equal(engine.resistance(p,'PHYSICAL'),.2);assert.equal(engine.resistance(p,'MAGICAL'),.1);engine.endTurn(state,'p');assert.equal(engine.resistance(p,'PHYSICAL'),.2);engine.endTurn(state,'p');assert.equal(engine.resistance(p,'PHYSICAL'),0);});
test('Combat V2 dash stops before its target and then deals damage',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',4,1),state=makeCombatState([p,m]);const result=makeCombatEngine().cast(state,{actorId:'p',ability:Abilities.avanco,target:{x:4,y:1}});assert(result.ok);assert.deepEqual({x:p.x,y:p.y},{x:3,y:1});assert.equal(m.hp,80);assert(eventTypes(result.events).includes('UNIT_MOVED'));});
test('Combat V2 dash rejects an enemy hidden behind another unit',()=>{const p=makeUnit('p','player',1,1),blocker=makeUnit('blocker','mob',2,1),target=makeUnit('target','mob',4,1),state=makeCombatState([p,blocker,target]);const result=makeCombatEngine().cast(state,{actorId:'p',ability:Abilities.avanco,target:{x:4,y:1}});assert.equal(result.ok,false);assert.equal(result.reason,'PATH');assert.equal(p.pa,6);assert.equal(target.hp,100);});
test('Combat V2 emits one death event per combatant',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',2,1,{hp:20}),state=makeCombatState([p,m]),engine=makeCombatEngine();const ability={id:'kill',apCost:0,range:{min:1,max:1},targeting:{targetType:'ENEMY'},effects:[{type:'DAMAGE',target:'TARGET',amount:30},{type:'DAMAGE',target:'TARGET',amount:30}]};const result=engine.cast(state,{actorId:'p',ability,target:{x:2,y:1}});assert.equal(m.hp,0);assert.equal(eventTypes(result.events).filter(type=>type==='UNIT_DIED').length,1);});
test('Combat V2 poison death prevents PA restoration',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',2,1,{hp:8,pa:1}),state=makeCombatState([p,m]),engine=makeCombatEngine();m.effects.push({id:'POISON',sourceId:'p',statusId:'POISON',duration:1,modifiers:{},tick:{damageType:'PHYSICAL',amount:8}});const result=engine.startTurn(state,'m');assert.equal(result.ok,false);assert.equal(m.hp,0);assert.equal(m.pa,1);assert(eventTypes(result.events).includes('UNIT_DIED'));});
test('Combat V2 event sequence is ordered and monotonic',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',2,1),state=makeCombatState([p,m]);const result=makeCombatEngine().cast(state,{actorId:'p',ability:{id:'hit',apCost:0,range:{min:1,max:1},targeting:{targetType:'ENEMY'},effects:[{type:'DAMAGE',target:'TARGET',amount:10}]},target:{x:2,y:1}});assert.deepEqual(eventTypes(result.events),['ABILITY_CAST','DAMAGE_APPLIED']);assert.deepEqual(result.events.map(e=>e.id),['combat-event:1','combat-event:2']);});
test('Smoke Combat V2: cast, poison tick, area damage and death event',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',3,1,{hp:50,maxHp:50}),state=makeCombatState([p,m]),engine=makeCombatEngine(),events=[];events.push(...engine.cast(state,{actorId:'p',ability:Abilities.lanca,target:{x:3,y:1}}).events);engine.endTurn(state,'p');events.push(...engine.startTurn(state,'m').events);engine.endTurn(state,'m');engine.startTurn(state,'p');events.push(...engine.cast(state,{actorId:'p',ability:Abilities.cruz,target:{x:3,y:1}}).events);assert.equal(m.hp,0);assert.equal(eventTypes(events).filter(type=>type==='UNIT_DIED').length,1);assert(eventTypes(events).includes('STATUS_APPLIED'));assert(eventTypes(events).includes('DAMAGE_APPLIED'));});

// Mission 7A: deterministic melee planning and safe path application.
const meleeAbility={id:'melee_test',apCost:3,cooldown:0,range:{min:1,max:1},requiresLoS:false,targeting:{targetType:'ENEMY',shape:'SINGLE'},effects:[{type:'DAMAGE',target:'TARGET',amount:10}]};
test('Melee AI attacks an adjacent target without moving',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',2,1),state=makeCombatState([p,m]);const plan=CombatAI.planMeleeTurn(state,m,meleeAbility);assert(plan.ok);assert.equal(plan.targetId,'p');assert.deepEqual(plan.path,[]);});
test('Melee AI approaches a distant target within PM',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',5,1,{pm:3}),state=makeCombatState([p,m]);const plan=CombatAI.planMeleeTurn(state,m,meleeAbility);assert(plan.ok);assert.equal(plan.path.length,3);const moved=CombatAI.applyPath(state,m,plan.path,Rules);assert(moved.ok);assert.deepEqual({x:m.x,y:m.y},{x:2,y:1});assert.equal(m.pm,0);});
test('Melee AI refuses a route that exceeds PM',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',5,1,{pm:2}),state=makeCombatState([p,m]);assert.equal(CombatAI.planMeleeTurn(state,m,meleeAbility).reason,'NO_PATH');});
test('Melee AI routes around an obstacle without crossing it',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',4,1,{pm:4}),state=makeCombatState([p,m]);state.board[1][3]='obstacle';const plan=CombatAI.planMeleeTurn(state,m,meleeAbility);assert(plan.ok);assert(plan.path.every(cell=>!(cell.x===3&&cell.y===1)));assert(CombatAI.applyPath(state,m,plan.path,Rules).ok);});
test('Melee AI routes around a blocking unit',()=>{const p=makeUnit('p','player',1,1),blocker=makeUnit('blocker','mob',3,1),m=makeUnit('m','mob',4,1,{pm:4}),state=makeCombatState([p,blocker,m]);const plan=CombatAI.planMeleeTurn(state,m,meleeAbility);assert(plan.ok);assert(plan.path.every(cell=>!(cell.x===3&&cell.y===1)));assert(CombatAI.applyPath(state,m,plan.path,Rules).ok);});
test('Melee AI movement never overlaps an occupied cell',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',2,1),state=makeCombatState([p,m]);const before={x:m.x,y:m.y,pm:m.pm};const result=CombatAI.applyPath(state,m,[{x:1,y:1}],Rules);assert.equal(result.ok,false);assert.deepEqual({x:m.x,y:m.y,pm:m.pm},before);});
test('Melee AI can move and attack in the same turn through the engine',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',5,1,{pm:3}),state=makeCombatState([p,m]),engine=makeCombatEngine();const plan=CombatAI.planMeleeTurn(state,m,meleeAbility);assert(CombatAI.applyPath(state,m,plan.path,Rules).ok);const cast=engine.cast(state,{actorId:m.id,ability:meleeAbility,target:{x:p.x,y:p.y}});assert(cast.ok);assert.equal(m.x,2);assert.equal(p.hp,90);});
test('Melee AI does not move or launch without enough PA',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',5,1,{pm:3,pa:2}),state=makeCombatState([p,m]);const plan=CombatAI.planMeleeTurn(state,m,meleeAbility);assert.equal(plan.reason,'PA');assert.deepEqual({x:m.x,y:m.y,pm:m.pm},{x:5,y:1,pm:3});});
test('Melee AI does not move or launch a cooldown ability',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',5,1,{pm:3,cooldowns:{melee_test:1}}),state=makeCombatState([p,m]);assert.equal(CombatAI.planMeleeTurn(state,m,meleeAbility).reason,'COOLDOWN');});
test('Melee AI rejects an invalid path atomically',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',4,1),state=makeCombatState([p,m]);state.board[1][3]='obstacle';const before={x:m.x,y:m.y,pm:m.pm};const result=CombatAI.applyPath(state,m,[{x:3,y:1}],Rules);assert.equal(result.ok,false);assert.deepEqual({x:m.x,y:m.y,pm:m.pm},before);});
test('Melee AI ends with no action when every route is blocked',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',4,1,{pm:5}),state=makeCombatState([p,m]);for(let y=0;y<state.board.length;y++)state.board[y][3]='obstacle';assert.equal(CombatAI.planMeleeTurn(state,m,meleeAbility).reason,'NO_PATH');});
test('Melee AI stops planning after the target dies',()=>{const p=makeUnit('p','player',1,1,{hp:10}),m=makeUnit('m','mob',2,1),state=makeCombatState([p,m]),engine=makeCombatEngine();const kill={...meleeAbility,id:'kill',effects:[{type:'DAMAGE',target:'TARGET',amount:20}]};const plan=CombatAI.planMeleeTurn(state,m,kill);assert(plan.ok);const result=engine.cast(state,{actorId:m.id,ability:kill,target:{x:p.x,y:p.y}});assert(result.ok);assert.equal(p.hp,0);assert.equal(CombatAI.planMeleeTurn(state,m,kill).reason,'NO_PATH');});

// Mission 7B: fixtures stay in tests; no canonical mob/content is added.
const rangedAbility={id:'ranged_test',apCost:3,cooldown:0,range:{min:2,max:3},requiresLoS:true,targeting:{targetType:'ENEMY',shape:'SINGLE'},effects:[{type:'DAMAGE',target:'TARGET',damageType:'MAGICAL',amount:10}]};
const controlAbility={id:'control_test',apCost:2,cooldown:1,range:{min:1,max:3},requiresLoS:true,targeting:{targetType:'ENEMY',shape:'SINGLE'},effects:[{type:'STATUS',target:'TARGET',statusId:'ROOTED',duration:1,modifiers:{}}]};
const healAbility={id:'heal_test',apCost:2,cooldown:1,range:{min:1,max:3},requiresLoS:true,targeting:{targetType:'ALLY',shape:'SINGLE'},effects:[{type:'HEAL',target:'TARGET',amount:20}]};
const supportBuff={id:'buff_test',apCost:2,cooldown:0,range:{min:0,max:0},requiresLoS:false,targeting:{targetType:'SELF',shape:'SINGLE'},effects:[{type:'BUFF',target:'SELF',statusId:'GUARDED',duration:2,modifiers:{physicalResistance:.1}}]};

test('Ranged AI attacks in range without moving',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',3,1),state=makeCombatState([p,m]);const plan=CombatAI.planRangedTurn(state,m,[rangedAbility]);assert(plan.ok);assert.equal(plan.targetId,'p');assert.deepEqual(plan.path,[]);});
test('Ranged AI seeks a position when beyond maximum range',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',5,1,{pm:2}),state=makeCombatState([p,m]);const plan=CombatAI.planRangedTurn(state,m,[rangedAbility]);assert(plan.ok);assert(plan.path.length>0);assert(plan.targetDistance<=3);});
test('Ranged AI respects minimum range',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',2,1,{pm:2}),state=makeCombatState([p,m]);const plan=CombatAI.planRangedTurn(state,m,[rangedAbility]);assert(plan.ok);assert(plan.path.length>0);assert(plan.targetDistance>=2);});
test('Ranged AI respects maximum range',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',5,1,{pm:2}),state=makeCombatState([p,m]);const plan=CombatAI.planRangedTurn(state,m,[rangedAbility]);assert(plan.ok);assert(plan.targetDistance<=rangedAbility.range.max);});
test('Ranged AI respects line of sight',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',3,1,{pm:4}),state=makeCombatState([p,m]);state.board[1][2]='obstacle';const plan=CombatAI.planRangedTurn(state,m,[rangedAbility]);assert(plan.ok);assert(CombatAI.applyPath(state,m,plan.path,Rules).ok);assert(CombatEffects.createCombatEngine({rules:Rules,rng:combatRng()}).lineOfSight(state,m,p));});
test('Ranged AI routes around an obstacle when a valid LoS remains',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',4,1,{pm:4}),state=makeCombatState([p,m]);state.board[1][3]='obstacle';const plan=CombatAI.planRangedTurn(state,m,[rangedAbility]);assert(plan.ok);assert(plan.path.every(cell=>!(cell.x===3&&cell.y===1)));});
test('Ranged AI respects units as blocked cells',()=>{const p=makeUnit('p','player',1,1),blocker=makeUnit('blocker','mob',3,1),m=makeUnit('m','mob',4,1,{pm:4}),state=makeCombatState([p,blocker,m]);const plan=CombatAI.planRangedTurn(state,m,[rangedAbility]);assert(plan.ok);assert(plan.path.every(cell=>!(cell.x===3&&cell.y===1)));});
test('Ranged AI never overlaps a unit while moving',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',2,1),state=makeCombatState([p,m]);const result=CombatAI.applyPath(state,m,[{x:1,y:1}],Rules);assert.equal(result.ok,false);assert.deepEqual({x:m.x,y:m.y},{x:2,y:1});});
test('Ranged AI respects PM before choosing a position',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',5,1,{pm:0}),state=makeCombatState([p,m]);assert.equal(CombatAI.planRangedTurn(state,m,[rangedAbility]).reason,'NO_PATH');});
test('Ranged AI respects PA before moving',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',5,1,{pm:2,pa:2}),state=makeCombatState([p,m]);assert.equal(CombatAI.planRangedTurn(state,m,[rangedAbility]).reason,'PA');assert.equal(m.x,5);});
test('Ranged AI respects cooldown before moving',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',5,1,{pm:2,cooldowns:{ranged_test:1}}),state=makeCombatState([p,m]);assert.equal(CombatAI.planRangedTurn(state,m,[rangedAbility]).reason,'COOLDOWN');});
test('Ranged AI moves and attacks through CombatEffectEngine',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',5,1,{pm:2}),state=makeCombatState([p,m]),engine=makeCombatEngine();const plan=CombatAI.planRangedTurn(state,m,[rangedAbility]);assert(CombatAI.applyPath(state,m,plan.path,Rules).ok);const cast=engine.cast(state,{actorId:m.id,ability:rangedAbility,target:{x:p.x,y:p.y}});assert(cast.ok);assert.equal(p.hp,90);});
test('Ranged AI increases distance when pressed if a ranged position is available',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',2,1,{pm:2}),state=makeCombatState([p,m]);const plan=CombatAI.planRangedTurn(state,m,[rangedAbility]);assert(plan.ok);assert(plan.path.length>0);assert(plan.targetDistance>=2);});
test('Ranged AI avoids partial mutation on an invalid path',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',4,1),state=makeCombatState([p,m]);const before={x:m.x,y:m.y,pm:m.pm};const result=CombatAI.applyPath(state,m,[{x:3,y:1},{x:2,y:2}],Rules);assert.equal(result.ok,false);assert.deepEqual({x:m.x,y:m.y,pm:m.pm},before);});
test('Ranged AI ends without an action when no target position exists',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',2,1,{pm:0}),state=makeCombatState([p,m]);state.board[1][2]='obstacle';assert.equal(CombatAI.planRangedTurn(state,m,[rangedAbility]).ok,false);});

test('Control AI selects a valid status ability',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',3,1),state=makeCombatState([p,m]);const plan=CombatAI.planControlTurn(state,m,[controlAbility]);assert(plan.ok);assert.equal(plan.ability.id,'control_test');});
test('Control AI does not select an invalid target',()=>{const ally=makeUnit('ally','mob',1,1),m=makeUnit('m','mob',2,1),state=makeCombatState([ally,m]);assert.equal(CombatAI.planControlTurn(state,m,[controlAbility]).ok,false);});
test('Control AI blocks on insufficient PA',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',2,1,{pa:1}),state=makeCombatState([p,m]);assert.equal(CombatAI.planControlTurn(state,m,[controlAbility]).reason,'PA');});
test('Control AI blocks on cooldown',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',2,1,{cooldowns:{control_test:1}}),state=makeCombatState([p,m]);assert.equal(CombatAI.planControlTurn(state,m,[controlAbility]).reason,'COOLDOWN');});
test('Control AI moves into range when possible',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',5,1,{pm:3}),state=makeCombatState([p,m]);const plan=CombatAI.planControlTurn(state,m,[controlAbility]);assert(plan.ok);assert(plan.path.length>0);assert(CombatAI.applyPath(state,m,plan.path,Rules).ok);});
test('Control AI respects line of sight',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',3,1,{pm:0}),state=makeCombatState([p,m]);state.board[1][2]='obstacle';assert.equal(CombatAI.planControlTurn(state,m,[controlAbility]).ok,false);});
test('Control effect is resolved by CombatEffectEngine',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',2,1),state=makeCombatState([p,m]),engine=makeCombatEngine();const plan=CombatAI.planControlTurn(state,m,[controlAbility]);const result=engine.cast(state,{actorId:m.id,ability:controlAbility,target:{x:p.x,y:p.y}});assert(plan.ok&&result.ok);assert.equal(p.effects[0].statusId,'ROOTED');});
test('Automatic decision prefers control over damage when both are valid',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',2,1),state=makeCombatState([p,m]),damage={...meleeAbility,id:'damage_alt'};const plan=CombatAI.planTurn(state,m,[damage,controlAbility]);assert(plan.ok);assert.equal(plan.ability.id,'control_test');});

test('Support AI identifies a wounded living ally',()=>{const ally=makeUnit('ally','mob',1,1,{hp:50}),m=makeUnit('m','mob',3,1),state=makeCombatState([ally,m]);const plan=CombatAI.planSupportTurn(state,m,[healAbility]);assert(plan.ok);assert.equal(plan.targetId,'ally');});
test('Support AI does not heal a full ally',()=>{const ally=makeUnit('ally','mob',1,1),m=makeUnit('m','mob',2,1),state=makeCombatState([ally,m]);assert.equal(CombatAI.planSupportTurn(state,m,[healAbility]).ok,false);});
test('Support AI does not heal a dead ally',()=>{const ally=makeUnit('ally','mob',1,1,{hp:0}),m=makeUnit('m','mob',2,1),state=makeCombatState([ally,m]);assert.equal(CombatAI.planSupportTurn(state,m,[healAbility]).ok,false);});
test('Support AI respects support range',()=>{const ally=makeUnit('ally','mob',1,1,{hp:50}),m=makeUnit('m','mob',5,1,{pm:0}),state=makeCombatState([ally,m]);assert.equal(CombatAI.planSupportTurn(state,m,[healAbility]).ok,false);});
test('Support AI respects PA',()=>{const ally=makeUnit('ally','mob',1,1,{hp:50}),m=makeUnit('m','mob',2,1,{pa:1}),state=makeCombatState([ally,m]);assert.equal(CombatAI.planSupportTurn(state,m,[healAbility]).reason,'PA');});
test('Support AI respects cooldown',()=>{const ally=makeUnit('ally','mob',1,1,{hp:50}),m=makeUnit('m','mob',2,1,{cooldowns:{heal_test:1}}),state=makeCombatState([ally,m]);assert.equal(CombatAI.planSupportTurn(state,m,[healAbility]).reason,'COOLDOWN');});
test('Support AI can move and heal through CombatEffectEngine',()=>{const ally=makeUnit('ally','mob',1,1,{hp:50}),m=makeUnit('m','mob',4,1,{pm:2}),state=makeCombatState([ally,m]),engine=makeCombatEngine();const plan=CombatAI.planSupportTurn(state,m,[healAbility]);assert(CombatAI.applyPath(state,m,plan.path,Rules).ok);const result=engine.cast(state,{actorId:m.id,ability:healAbility,target:{x:ally.x,y:ally.y}});assert(result.ok);assert.equal(ally.hp,70);});
test('Support effect is resolved as a HEAL event',()=>{const ally=makeUnit('ally','mob',1,1,{hp:50}),m=makeUnit('m','mob',2,1),state=makeCombatState([ally,m]),engine=makeCombatEngine();const result=engine.cast(state,{actorId:m.id,ability:healAbility,target:{x:ally.x,y:ally.y}});assert(result.ok);assert(eventTypes(result.events).includes('HEAL_APPLIED'));});

test('Pack AI prevents two melee units from choosing the same occupied cell',()=>{const p=makeUnit('p','player',1,1),a=makeUnit('a','mob',5,1,{pm:3}),b=makeUnit('b','mob',5,2,{pm:4}),state=makeCombatState([p,a,b]);const first=CombatAI.planMeleeTurn(state,a,meleeAbility);assert(CombatAI.applyPath(state,a,first.path,Rules).ok);const second=CombatAI.planMeleeTurn(state,b,meleeAbility);assert(second.ok);assert.notDeepEqual(second.cell,{x:a.x,y:a.y});});
test('Pack AI tie-breaking is deterministic',()=>{const p=makeUnit('p','player',2,2),m=makeUnit('m','mob',5,2,{pm:3}),state=makeCombatState([p,m]);const first=CombatAI.planMeleeTurn(state,m,meleeAbility),second=CombatAI.planMeleeTurn(state,m,meleeAbility);assert.deepEqual(first.path,second.path);});
test('Pack preference is secondary to shortest valid action',()=>{const p=makeUnit('p','player',1,1),ally=makeUnit('ally','mob',2,2),m=makeUnit('m','mob',5,1,{pm:3}),state=makeCombatState([p,ally,m]);const plan=CombatAI.planMeleeTurn(state,m,meleeAbility);assert(plan.ok);assert.equal(plan.path.length,3);});
test('Pack planner works without allies',()=>{const p=makeUnit('p','player',1,1),m=makeUnit('m','mob',3,1),state=makeCombatState([p,m]);assert(CombatAI.planMeleeTurn(state,m,meleeAbility).ok);});

// Mission 8: Economy V1 remains DOM-free and atomic.
test('Economy starts with zero base currency',()=>assert.equal(makeEconomy().getBalance(),0));
test('Economy adds and removes currency without going negative',()=>{const p={},pr={currency:{}};const e=makeEconomy(p,pr);assert(e.addCurrency(20).ok);assert(e.removeCurrency(7).ok);assert.equal(e.getBalance(),13);assert.equal(e.removeCurrency(99).ok,false);assert.equal(e.getBalance(),13);});
test('Economy rejects negative currency',()=>{const e=makeEconomy();assert.equal(e.addCurrency(-1).ok,false);assert.equal(e.getBalance(),0);});
test('Economy buys a valid item atomically',()=>{const p={inventory:{}},pr={currency:{base:20}},e=makeEconomy(p,pr);const r=e.buy('pocao_simples',1);assert(r.ok);assert.equal(p.inventory.pocao_simples,1);assert.equal(e.getBalance(),8);});
test('Economy rejects purchase with insufficient funds atomically',()=>{const p={inventory:{}},pr={currency:{base:2}},e=makeEconomy(p,pr);assert.equal(e.buy('pocao_simples',1).ok,false);assert.deepEqual(p.inventory,{});assert.equal(e.getBalance(),2);});
test('Economy rejects unknown and invalid quantity',()=>{const e=makeEconomy({}, {currency:{base:99}});assert.equal(e.buy('missing',1).reason,'UNKNOWN_ITEM');assert.equal(e.buy('sword',0).reason,'INVALID_QUANTITY');});
test('Economy buys requested quantity atomically',()=>{const p={inventory:{}},pr={currency:{base:40}},e=makeEconomy(p,pr);assert(e.buy('sword',3).ok);assert.equal(p.inventory.sword,3);assert.equal(e.getBalance(),10);});
test('Economy sells a valid item and credits balance',()=>{const p={inventory:{sword:2}},pr={currency:{base:1}},e=makeEconomy(p,pr);assert(e.sell('sword',1).ok);assert.equal(p.inventory.sword,1);assert.equal(e.getBalance(),6);});
test('Economy rejects selling too many items atomically',()=>{const p={inventory:{sword:1}},pr={currency:{base:1}},e=makeEconomy(p,pr);assert.equal(e.sell('sword',2).ok,false);assert.equal(p.inventory.sword,1);assert.equal(e.getBalance(),1);});
test('Economy protects unsellable and quest items',()=>{const p={inventory:{hide:1,quest:1}},e=makeEconomy(p,{currency:{}});assert.equal(e.sell('hide',1).reason,'UNSELLABLE_ITEM');assert.equal(e.sell('quest',1).reason,'UNSELLABLE_ITEM');assert.equal(p.inventory.hide,1);});
test('Economy buy and sell emit one coherent mutation',()=>{let events=0;const p={inventory:{}},pr={currency:{base:20}},e=EconomyApi.createEconomySystem({playerProvider:()=>p,progressionProvider:()=>pr,itemDb:economyItems,catalog:economyCatalog,onChanged:()=>events++});e.buy('sword',1);e.sell('sword',1);assert.equal(events,2);assert.equal(e.getBalance(),15);});
test('Economy save/load preserves currency inventory and equipment',()=>{const state=baseSnapshot();state.progression.currency.base=17;state.player.inventory.hide=2;state.player.equipment.hat='hat';const storage=new Persistence.MemoryStorageAdapter(),s=makePersistence(storage,state);s.saveNow();const loaded=makePersistence(storage).load();assert.equal(loaded.progression.currency.base,17);assert.equal(loaded.player.inventory.hide,2);assert.equal(loaded.player.equipment.hat,'hat');});
test('Persistence clamps negative currency',()=>{const s=makePersistence(new Persistence.MemoryStorageAdapter());assert.deepEqual(s.sanitizeProgression({currency:{base:-4,other:3.9}}).currency,{other:3});});
test('Merchant role exposes open commerce action',()=>{const merchant={id:'m',role:'MERCHANT',mapId:'0,0',position:{x:1,y:1},dialogue:{greeting:'Olá'}};const n=NpcApi.createNpcSystem({npcDb:{m:merchant},worldProvider:()=>({currentMapId:'0,0',player:{x:1,y:1}})});const d=n.interact('m').dialogue;assert(d.options.some(o=>o.id==='open_merchant'));assert(n.execute('m',{id:'open_merchant'}).openMerchant);});
// Mission 9A: canonical content registry and referential integrity.
test('Fímbria registry contains the 9 canonical creatures',()=>{assert.equal(Object.values(Fimbria.creatures).filter(creature=>!creature.baseId).length,9);assert(Fimbria.creatures.CRE_SINEIRA);assert(Fimbria.creatures.CRE_CORUJA_MUDA);});
test('Fímbria exposures preserve the four canonical categories',()=>assert.deepEqual(Fimbria.exposures,['NORMAL','ORVALHADO','MAREJADO','ENCHARCADO']));
test('Fímbria variants do not invent global stat mechanics',()=>{assert.equal(Fimbria.creatures.CRE_FIANDEIRA_ENCHARCADA.mechanicsStatus,'variant_data_only');assert.equal(Fimbria.creatures.CRE_SINEIRA.mechanicsStatus,'boss_deferred');});
test('Fímbria registers exactly ENC_01 through ENC_12',()=>{const ids=Object.keys(Fimbria.encounters);assert.equal(ids.length,12);assert(ids.every(id=>/^ENC_(0[1-9]|1[0-2])$/.test(id)));assert.equal(Fimbria.encounters.ENC_13,undefined);});
test('Fímbria keeps owl and Sineira encounters separate and deferred',()=>{assert.equal(Fimbria.owlEncounter.mapId,'MAP_09');assert.equal(Fimbria.owlEncounter.status,'deferred');assert.equal(Fimbria.sineiraEncounter.mapId,'MAP_11');assert.equal(Fimbria.sineiraEncounter.status,'boss_deferred');});
test('Fímbria encounter compositions preserve maps and exposures',()=>{assert.equal(Fimbria.encounters.ENC_08.composition.length,3);assert.equal(Fimbria.encounters.ENC_08.composition[0].exposure,'MAREJADO');assert.equal(Fimbria.encounters.ENC_12.composition[0].exposure,'ENCHARCADO');});
test('Fímbria registers 11 canonical maps without visual layouts',()=>{assert.equal(Object.keys(Fimbria.maps).length,11);assert.equal(Fimbria.maps.MAP_01.type,'HUB');assert.equal(Fimbria.maps.MAP_11.bossReference,'CRE_SINEIRA');});
test('Fímbria registers MAIN_01..08 and SIDE_01..05',()=>{const ids=Object.keys(Fimbria.quests);assert.equal(ids.filter(id=>/^MAIN_0[1-8]$/.test(id)).length,8);assert.equal(ids.filter(id=>/^SIDE_0[1-5]$/.test(id)).length,5);});
test('Fímbria quest items are explicit and non-sellable',()=>{['QITEM_TUFO_PALIDO','QITEM_REGISTRO_DE_NIVEL','QITEM_PAGINA_DAS_BATIDAS','QITEM_PAGINAS_DE_AURELO','QITEM_DECALQUE_DO_SELO'].forEach(id=>assert(Fimbria.questItems[id]));});
test('Fímbria canonical NPC references stay within the four existing NPC roles',()=>assert.deepEqual(Fimbria.npcIds,['NPC_MIRA','NPC_LIA','NPC_NILO','NPC_BRAM']));
test('Fímbria legacy content is classified rather than silently canonized',()=>{assert.equal(Fimbria.legacy.javali.classification,'LEGACY NECESSÁRIO');assert.equal(Fimbria.legacy.cogumelo.canonical,false);});
test('Fímbria normalizes encounter aliases explicitly',()=>{assert.equal(Fimbria.aliases.ENC_E01,'ENC_01');assert.equal(Fimbria.aliases.NPC_BRAM,'mercador_bram');});
test('Fímbria cross-reference validator is clean',()=>{const result=Fimbria.validateReferences();assert.equal(result.ok,true);assert.deepEqual(result.errors,[]);});
// Mission 9B: small generic runtime extensions.
test('Quest OR accepts alternative A without requiring B',()=>{const q=QuestApi.createQuestSystem({questDb:{q:{id:'q',prerequisites:[],objectives:[{id:'route',type:'OR',alternatives:[{type:'EXPLORE',target:'A'},{type:'EXPLORE',target:'B'}],amount:1}],rewards:{}}},progression:{}});assert(q.acceptQuest('q'));q.recordEvent({type:'MAP_VISITED',mapId:'A',eventId:'a'});assert(q.isComplete('q'));});
test('Quest OR accepts alternative B and ignores invalid alternative',()=>{const q=QuestApi.createQuestSystem({questDb:{q:{id:'q',prerequisites:[],objectives:[{id:'route',type:'OR',alternatives:[{type:'EXPLORE',target:'A'},{type:'EXPLORE',target:'B'}],amount:1}],rewards:{}}},progression:{}});q.acceptQuest('q');q.recordEvent({type:'MAP_VISITED',mapId:'C',eventId:'c'});assert.equal(q.getObjectiveViews('q')[0].current,0);q.recordEvent({type:'MAP_VISITED',mapId:'B',eventId:'b'});assert(q.isComplete('q'));});
test('BOSS_RESOLVED event is recognized without implementing a boss',()=>{const q=QuestApi.createQuestSystem({questDb:{q:{id:'q',prerequisites:[],objectives:[{id:'boss',type:'BOSS',target:'SINEIRA',amount:1}],rewards:{}}},progression:{}});q.acceptQuest('q');q.recordEvent({type:'BOSS_RESOLVED',bossId:'SINEIRA',eventId:'boss'});assert(q.isComplete('q'));});
test('ENCOUNTER_RESOLVED and POINT_INSPECTED are generic events',()=>{const q=QuestApi.createQuestSystem({questDb:{q:{id:'q',prerequisites:[],objectives:[{id:'enc',type:'ENCOUNTER',target:'ENC_X',amount:1},{id:'point',type:'INSPECT',target:'seal',amount:1}],rewards:{}}},progression:{}});q.acceptQuest('q');q.recordEvent({type:'ENCOUNTER_RESOLVED',encounterId:'wrong',eventId:'wrong'});assert.equal(q.getObjectiveViews('q')[0].current,0);q.recordEvent({type:'ENCOUNTER_RESOLVED',encounterId:'ENC_X',eventId:'enc'});q.recordEvent({type:'POINT_INSPECTED',pointId:'seal',eventId:'point'});assert(q.isComplete('q'));});
test('Repeated generic event does not duplicate progress',()=>{const q=QuestApi.createQuestSystem({questDb:{q:{id:'q',prerequisites:[],objectives:[{id:'point',type:'INSPECT',target:'seal',amount:1}],rewards:{}}},progression:{}});q.acceptQuest('q');q.recordEvent({type:'POINT_INSPECTED',pointId:'seal',eventId:'same'});q.recordEvent({type:'POINT_INSPECTED',pointId:'seal',eventId:'same'});assert.equal(q.getObjectiveViews('q')[0].current,1);});
test('World flags set/read/clear with safe absent default',()=>{const p={flags:{}},w=WorldApi.createWorldState({progressionProvider:()=>p});assert.equal(w.hasFlag('FLAG_X'),false);assert(w.setFlag('FLAG_X').ok);assert.equal(w.hasFlag('FLAG_X'),true);assert(w.clearFlag('FLAG_X').ok);assert.equal(w.hasFlag('FLAG_X'),false);});
test('World inspection emits quest event and optional flag',()=>{let seen=0;const q=QuestApi.createQuestSystem({questDb:{q:{id:'q',prerequisites:[],objectives:[{id:'p',type:'INSPECT',target:'cisterna',amount:1}],rewards:{}}},progression:{},onChanged:()=>{seen++;}});q.acceptQuest('q');const p={flags:{}},w=WorldApi.createWorldState({progressionProvider:()=>p,questSystem:q});const first=w.inspect('cisterna',{flag:'FLAG_CISTERNA'});assert(first.ok);assert.equal(first.flagChanged,true);assert.equal(w.hasFlag('FLAG_CISTERNA'),true);assert.equal(q.getObjectiveViews('q')[0].current,1);assert(seen>0);});
test('World reinspection is safe and does not duplicate quest progress',()=>{const q=QuestApi.createQuestSystem({questDb:{q:{id:'q',prerequisites:[],objectives:[{id:'p',type:'INSPECT',target:'cisterna',amount:1}],rewards:{}}},progression:{}});q.acceptQuest('q');const w=WorldApi.createWorldState({progressionProvider:()=>({flags:{}}),questSystem:q});w.inspect('cisterna');w.inspect('cisterna');assert.equal(q.getObjectiveViews('q')[0].current,1);});
test('World flags persist through SaveSystem V2',()=>{const state=baseSnapshot(),w=WorldApi.createWorldState({progressionProvider:()=>state.progression});w.setFlag('FLAG_CARROCAL_UNLOCKED');const storage=new Persistence.MemoryStorageAdapter(),s=makePersistence(storage,state);s.saveNow();assert.equal(makePersistence(storage).load().progression.flags.FLAG_CARROCAL_UNLOCKED,true);});
test('Gate is closed before flag and open after flag',()=>{const flags={};const g=GateApi.createGateEngine({flagProvider:id=>flags[id]===true});const rule={id:'carrocal',from:'MAP_01',to:'MAP_04',requiresFlag:'FLAG_CARROCAL_UNLOCKED',bidirectional:true};assert.deepEqual(g.destinations('MAP_01',[rule]),[]);flags.FLAG_CARROCAL_UNLOCKED=true;assert.deepEqual(g.destinations('MAP_01',[rule]),['MAP_04']);assert.deepEqual(g.destinations('MAP_04',[rule]),['MAP_01']);});
test('Canonical Carroçal gate is open without a progression flag',()=>{const flags={};const g=GateApi.createGateEngine({flagProvider:id=>flags[id]===true});const rule=Fimbria.exits.find(e=>e.id==='EXIT_CARROCAL');assert.equal(g.isOpen(rule),true);assert.deepEqual(g.destinations('MAP_01',[rule]),['MAP_04']);});
test('MAIN_02 completion grants its persistent Carroçal story flag without gating access',()=>{const flags={},progression={MAIN_01:{state:'COMPLETED',progress:{},seenEvents:{},rewardClaimed:true}},q=QuestApi.createQuestSystem({questDb:{MAIN_01:Fimbria.quests.MAIN_01,MAIN_02:Fimbria.quests.MAIN_02},progression,autoComplete:false,flagSink:flag=>{flags[flag]=true;}});assert(q.acceptQuest('MAIN_02'));q.recordEvent({type:'MAP_VISITED',mapId:'MAP_04',eventId:'map'});q.recordEvent({type:'ITEM_ACQUIRED',itemId:'QITEM_TUFO_PALIDO',eventId:'tufo'});q.recordEvent({type:'MOB_KILLED',mobType:'CRE_TOPETAO',eventId:'topetao'});q.recordEvent({type:'NPC_TALKED',npcId:'NPC_LIA',eventId:'lia'});assert(q.completeQuest('MAIN_02'));assert.equal(flags.FLAG_CARROCAL_UNLOCKED,true);assert.equal(FimbriaRuntime.prepareTransition({mapId:'MAP_01',exitId:'EXIT_CARROCAL'}).ok,true);});
test('Canonical stair gate remains closed until its TBD flag',()=>{const flags={};const g=GateApi.createGateEngine({flagProvider:id=>flags[id]===true});const rule=Fimbria.exits.find(e=>e.id==='EXIT_ESCADA_MARCO_PRUMO');assert.equal(rule.status,'prepared_tbd');assert.equal(g.isOpen(rule),false);});
test('All 13 canonical quests expose an explicit runtime classification',()=>{assert.equal(Object.keys(Fimbria.quests).length,13);Object.values(Fimbria.quests).forEach(q=>assert(['FUNCIONAL','PARTIAL','DATA-ONLY','BLOCKED'].includes(q.runtimeStatus)));});
// Mission 9C: canonical runtime adapters.
test('Seven normal Fímbria creatures load into runtime templates',()=>{assert.equal(FimbriaRuntime.normalCreatureIds.length,7);FimbriaRuntime.normalCreatureIds.forEach(id=>assert(FimbriaRuntime.resolveCreature(id)));});
test('Canonical runtime creature IDs are unique',()=>assert.equal(new Set(Object.keys(FimbriaRuntime.templates)).size,Object.keys(FimbriaRuntime.templates).length));
test('Coruja and Sineira are excluded from normal runtime templates',()=>{assert.equal(FimbriaRuntime.resolveCreature('CRE_CORUJA_MUDA'),null);assert.equal(FimbriaRuntime.resolveCreature('CRE_SINEIRA'),null);});
test('Valid exposure variant resolves without global multiplier',()=>{const v=FimbriaRuntime.resolveCreature('CRE_FIANDEIRA_ENCHARCADA');assert.equal(v.exposure,'ENCHARCADO');assert.equal(v.template.variantMetadata.exposure,'ENCHARCADO');assert.equal(v.template.damageMultiplier,undefined);});
test('Unknown exposure variant is rejected safely',()=>assert.equal(FimbriaRuntime.resolveCreature('CRE_FIANDEIRA_INEXISTENTE'),null));
test('Runtime numbers are centralized and provisional',()=>{FimbriaRuntime.normalCreatureIds.forEach(id=>{const t=FimbriaRuntime.templates[id];assert.equal(t.provisionalBalance,true);assert(String(t.balanceNote).includes('PROVISÓRIO'));});});
test('ENC_01 through ENC_12 resolve into runtime compositions',()=>{for(let i=1;i<=12;i++){const id=`ENC_${String(i).padStart(2,'0')}`,result=FimbriaRuntime.createEncounterSpec(id);assert(result.ok);assert(result.mobsSpec.length>0);}});
test('Runtime encounter creates combatants from canonical IDs',()=>{const result=FimbriaRuntime.createCombatants('ENC_08');assert(result.ok);assert.equal(result.combatants.length,3);assert(result.combatants.every(c=>c.canonicalId&&c.exposure));});
test('Unsupported creature fails encounter creation without partial combatants',()=>{const original=Fimbria.encounters.ENC_01.composition;Fimbria.encounters.ENC_01.composition=[{creatureId:'CRE_SINEIRA',exposure:'NORMAL'}];const result=FimbriaRuntime.createEncounterSpec('ENC_01');Fimbria.encounters.ENC_01.composition=original;assert.equal(result.ok,false);assert.equal(result.reason,'UNSUPPORTED_CREATURE');});
test('ENC_13 remains absent from runtime adapter',()=>assert.equal(FimbriaRuntime.createEncounterSpec('ENC_13').reason,'UNKNOWN_ENCOUNTER'));
test('All canonical maps are recognized as provisional runtime adapters',()=>{for(let i=1;i<=11;i++){const id=`MAP_${String(i).padStart(2,'0')}`;const map=FimbriaRuntime.resolveMap(id);assert(map);assert.equal(map.layoutStatus,'placeholder');}});
test('TBD topology is not converted into runtime connections',()=>{assert.equal(Fimbria.maps.MAP_05.connections.includes('MAP_07'),true);assert.equal(Fimbria.maps.MAP_05.tbd.includes('MAP_07 gate'),true);assert.equal(Fimbria.exits.find(e=>e.id==='EXIT_ESCADA_MARCO_PRUMO').status,'prepared_tbd');});
test('Canonical quest event adapter normalizes NPC aliases only',()=>{const npc=FimbriaRuntime.adaptQuestEvent({type:'NPC_TALKED',npcId:'guarda_mira'});assert.equal(npc.npcId,'NPC_MIRA');const mob=FimbriaRuntime.adaptQuestEvent({type:'MOB_KILLED',mobType:'CRE_TOPETAO'});assert.equal(mob.mobType,'CRE_TOPETAO');});
test('Canonical KILL objective consumes canonical mob event',()=>{const q=QuestApi.createQuestSystem({questDb:{q:{id:'q',prerequisites:[],objectives:[{id:'k',type:'KILL',target:'CRE_TOPETAO',amount:1}],rewards:{}}},progression:{}});q.acceptQuest('q');q.recordEvent(FimbriaRuntime.adaptQuestEvent({type:'MOB_KILLED',mobType:'CRE_TOPETAO',eventId:'k'}));assert(q.isComplete('q'));});
test('Canonical EXPLORE, TALK and COLLECT objectives use stable IDs',()=>{const db={q:{id:'q',prerequisites:[],objectives:[{id:'m',type:'EXPLORE',target:'MAP_04',amount:1},{id:'n',type:'TALK',target:'NPC_LIA',amount:1},{id:'i',type:'COLLECT',target:'QITEM_TUFO_PALIDO',amount:1}],rewards:{}}};const q=QuestApi.createQuestSystem({questDb:db,progression:{},autoComplete:false});q.acceptQuest('q');q.recordEvent({type:'MAP_VISITED',mapId:'MAP_04',eventId:'m'});q.recordEvent(FimbriaRuntime.adaptQuestEvent({type:'NPC_TALKED',npcId:'exploradora_lia',eventId:'n'}));q.recordEvent({type:'ITEM_ACQUIRED',itemId:'QITEM_TUFO_PALIDO',eventId:'i'});assert.equal(q.getObjectiveViews('q').filter(o=>o.complete).length,3);});
// Mission 10A: minimal non-lethal boss contract.
const sineiraBossOptions={bossId:'CRE_SINEIRA',name:'Sineira',phases:Fimbria.bosses.CRE_SINEIRA.phases,initialPhase:'GUARDIA',nonLethal:true,exposure:Fimbria.bosses.CRE_SINEIRA.exposure,transitions:[{from:'GUARDIA',to:'ALVOROCO',when:{event:'ARENA_PRESSURE'}},{from:'ALVOROCO',to:'ALIVIO',when:{exposure:0}}]};
test('Sineira boss definition creates with non-lethal identity',()=>{const boss=BossApi.createBoss(sineiraBossOptions);assert(boss);assert.equal(boss.boss.bossId,'CRE_SINEIRA');assert.equal(boss.boss.nonLethal,true);assert.equal(boss.boss.state,'ACTIVE');});
test('Invalid boss definition is rejected safely',()=>{assert.equal(BossApi.createBoss({bossId:'',phases:['GUARDIA'],initialPhase:'GUARDIA'}),null);assert.equal(BossApi.createBoss({bossId:'X',phases:[],initialPhase:'GUARDIA'}),null);});
test('Sineira exposes exactly the three canonical phases',()=>{assert.deepEqual(Fimbria.bosses.CRE_SINEIRA.phases,['GUARDIA','ALVOROCO','ALIVIO']);assert.equal(Fimbria.bosses.CRE_SINEIRA.phases.includes('FASE_4'),false);});
test('Boss phase transition accepts declared condition and rejects undeclared transition',()=>{const boss=BossApi.createBoss(sineiraBossOptions);assert.equal(boss.transition('ALVOROCO',{event:'WRONG'}).ok,false);assert(boss.transition('ALVOROCO',{event:'ARENA_PRESSURE'}).ok);assert.equal(boss.transition('GUARDIA').ok,false);});
test('Boss telegraph lifecycle is pending, resolvable, cancellable and single-use',()=>{const boss=BossApi.createBoss(sineiraBossOptions);const created=boss.createTelegraph({abilityId:'SINEIRA_INTENT',target:{kind:'AREA'},resolveTurn:3});assert(created.ok);assert.equal(boss.getTelegraph(created.telegraph.id).status,'PENDING');assert(boss.resolveTelegraph(created.telegraph.id).ok);assert.equal(boss.resolveTelegraph(created.telegraph.id).ok,false);const second=boss.createTelegraph({abilityId:'OTHER'});assert(boss.cancelTelegraph(second.telegraph.id).ok);assert.equal(boss.cancelTelegraph(second.telegraph.id).ok,false);});
test('Sineira exposure can be queried, increased, reduced and clamped',()=>{const boss=BossApi.createBoss(sineiraBossOptions);assert.equal(boss.snapshot().exposure.value,50);assert.equal(boss.changeExposure(20).value,70);assert.equal(boss.changeExposure(-200).value,0);assert.equal(boss.changeExposure(1000).value,100);});
test('Non-lethal boss damage never emits normal death',()=>{const boss=BossApi.createBoss(sineiraBossOptions);const result=boss.applyDamage(9999);assert.equal(result.death,false);assert.equal(result.nonLethal,true);assert.equal(boss.boss.state,'CRITICAL');assert.equal(boss.boss.hp,1);});
test('Normal mob death rule remains unchanged',()=>{const mob={hp:5};assert.equal(Rules.applyDamage(mob,6),true);assert.equal(mob.hp,0);});
test('Boss resolution emits BOSS_RESOLVED once and is quest-consumable',()=>{const events=[],boss=BossApi.createBoss({...sineiraBossOptions,onEvent:event=>events.push(event)});const q=QuestApi.createQuestSystem({questDb:{q:{id:'q',prerequisites:[],objectives:[{id:'boss',type:'BOSS',target:'CRE_SINEIRA',amount:1}],rewards:{}}},progression:{}});q.acceptQuest('q');const resolved=boss.resolve({resolution:'NON_LETHAL',context:{arenaId:'MAP_11'}});assert(resolved.ok);assert.equal(resolved.event.nonLethal,true);q.recordEvent({...resolved.event,eventId:'sineira-once'});assert(q.isComplete('q'));assert.equal(boss.resolve().ok,false);assert.equal(events.filter(event=>event.type==='BOSS_RESOLVED').length,1);});
test('Resolved boss cannot change exposure or resolve telegraph again',()=>{const boss=BossApi.createBoss(sineiraBossOptions),telegraph=boss.createTelegraph({abilityId:'INTENT'});assert(boss.resolve().ok);assert.equal(boss.changeExposure(-10).ok,false);assert.equal(boss.resolveTelegraph(telegraph.telegraph.id).ok,false);assert.equal(boss.createTelegraph({abilityId:'LATE'}).ok,false);});
test('Arena metadata remains conceptual and coordinate-free',()=>{const arena=Fimbria.arenaMetadata.MAP_11;assert(arena.elements.includes('SELO_CENTRAL'));assert.equal(arena.coordinates,'TBD');assert.equal(arena.layoutStatus,'placeholder');});
// Mission 10B: deterministic playable Sineira strategy over the 10A contracts.
test('Sineira encounter starts in GUARDIA with fixture-only arena data',()=>{const encounter=Sineira.createSineiraEncounter({cravas:['TEST_CRAVA_A','TEST_CRAVA_B']});assert(encounter);assert.equal(encounter.phase(),'GUARDIA');assert.equal(encounter.boss.snapshot().exposure.value,50);assert.equal(encounter.arena.arenaId,'MAP_11');assert.equal(encounter.arena.fixture,true);assert(encounter.arena.elements.includes('CRAVAS'));});
test('Invalid Sineira encounter definition is rejected safely',()=>assert.equal(Sineira.createSineiraEncounter({boss:{bossId:''}}),null));
test('Sineira phase progression is deterministic and has no fourth phase',()=>{const encounter=Sineira.createSineiraEncounter();assert.equal(encounter.beginTurn(1).phase,'GUARDIA');assert.equal(encounter.beginTurn(2).phase,'ALVOROCO');assert.deepEqual(encounter.boss.snapshot().phases,['GUARDIA','ALVOROCO','ALIVIO']);});
test('Sineira Batida telegraph remains pending until its later turn',()=>{const encounter=Sineira.createSineiraEncounter();encounter.beginTurn(1);const planned=encounter.planAction({actionId:'SINEIRA_BATIDA',target:{x:1,y:1}});assert(planned.ok);assert.equal(encounter.boss.getTelegraph(planned.telegraph.id).status,'PENDING');assert.equal(encounter.resolveAction(planned.telegraph.id).reason,'NOT_DUE');encounter.beginTurn(2);assert(encounter.resolveAction(planned.telegraph.id).ok);assert.equal(encounter.boss.getTelegraph(planned.telegraph.id).status,'RESOLVED');});
test('Sineira exposes the three supported deterministic actions',()=>{const encounter=Sineira.createSineiraEncounter();encounter.beginTurn(1);assert.deepEqual(encounter.actionsForPhase(),['BATIDA']);encounter.beginTurn(2);assert.deepEqual(encounter.actionsForPhase(),['PRESSAO']);encounter.beginTurn(3);assert.deepEqual(encounter.actionsForPhase(),['INVESTIDA']);});
test('Cravas reduce exposure once and reject invalid or repeated interaction',()=>{const encounter=Sineira.createSineiraEncounter({cravas:['TEST_CRAVA_A','TEST_CRAVA_B']});encounter.beginTurn(2);assert.equal(encounter.interactCrava('UNKNOWN').ok,false);assert.equal(encounter.interactCrava('TEST_CRAVA_A').pressure.value,25);assert.equal(encounter.interactCrava('TEST_CRAVA_A').reason,'ALREADY_USED');const second=encounter.interactCrava('TEST_CRAVA_B');assert.equal(second.pressure.value,0);assert.equal(encounter.phase(),'ALIVIO');});
test('Sineira resolves non-lethally only after ALIVIO objective',()=>{const events=[],encounter=Sineira.createSineiraEncounter({cravas:['A','B']});encounter.boss.onEvent=e=>events.push(e);encounter.beginTurn(2);encounter.interactCrava('A');encounter.interactCrava('B');const result=encounter.tryResolve({seal:'inspectable'});assert(result.ok);assert.equal(result.event.nonLethal,true);assert.equal(result.event.resolution,'NON_LETHAL');assert.equal(encounter.tryResolve().ok,false);assert.equal(events.filter(e=>e.type==='BOSS_RESOLVED').length,1);});
test('Sineira Batida resolves through CombatEffectEngine without same-turn shortcut',()=>{const encounter=Sineira.createSineiraEncounter();encounter.beginTurn(1);const boss=encounter.createBossCombatant({x:0,y:0}),player={id:'player',side:'player',x:1,y:0,hp:100,maxHp:100,pa:6,pm:4,maxPa:6,maxPm:4,cooldowns:{},effects:[],resistances:{PHYSICAL:0,MAGICAL:0},combatStats:{}};const state={board:Array.from({length:3},()=>Array(3).fill('empty')),combatants:[boss,player],eventSequence:0};const engine=CombatEffects.createCombatEngine({rules:Rules,rng:rng([1])});encounter.combatEngine=engine;const planned=encounter.planAction({actionId:'SINEIRA_BATIDA',target:{x:1,y:0}});assert.equal(player.hp,100);encounter.beginTurn(2);const result=encounter.resolveAction(planned.telegraph.id,state);assert(result.combat.ok);assert(player.hp<100);assert.equal(state.combatants.find(c=>c.id==='CRE_SINEIRA').nonLethalBoss,true);});
test('Sineira Pressão resolves later and changes only encounter exposure',()=>{const encounter=Sineira.createSineiraEncounter();encounter.beginTurn(2);const planned=encounter.planAction({actionId:'SINEIRA_PRESSAO'});assert(planned.ok);assert.equal(encounter.boss.snapshot().exposure.value,50);assert.equal(encounter.resolveAction(planned.telegraph.id).reason,'NOT_DUE');encounter.beginTurn(3);const result=encounter.resolveAction(planned.telegraph.id);assert(result.ok);assert.equal(result.pressure.value,65);});
test('Sineira Investida uses existing dash validation and resolves once',()=>{const encounter=Sineira.createSineiraEncounter();encounter.beginTurn(2);encounter.beginTurn(3);const boss=encounter.createBossCombatant({x:0,y:0}),player={id:'player',side:'player',x:2,y:0,hp:100,maxHp:100,pa:6,pm:4,maxPa:6,maxPm:4,cooldowns:{},effects:[],resistances:{PHYSICAL:0,MAGICAL:0},combatStats:{}};const state={board:Array.from({length:3},()=>Array(3).fill('empty')),combatants:[boss,player],eventSequence:0};const engine=CombatEffects.createCombatEngine({rules:Rules,rng:rng([1])});encounter.combatEngine=engine;const planned=encounter.planAction({actionId:'SINEIRA_INVESTIDA',target:{x:2,y:0}});assert(planned.ok);encounter.beginTurn(4);const result=encounter.resolveAction(planned.telegraph.id,state);assert(result.combat.ok);assert.equal(player.hp,90);assert.equal(encounter.resolveAction(planned.telegraph.id,state).ok,false);});
test('CombatEffectEngine keeps Sineira critical instead of UNIT_DIED',()=>{const encounter=Sineira.createSineiraEncounter(),boss=encounter.createBossCombatant({x:1,y:0}),player={id:'player',side:'player',x:0,y:0,hp:100,maxHp:100,pa:6,pm:4,maxPa:6,maxPm:4,cooldowns:{},effects:[],resistances:{PHYSICAL:0,MAGICAL:0},combatStats:{}};const state={board:Array.from({length:2},()=>Array(2).fill('empty')),combatants:[player,boss],eventSequence:0};const engine=CombatEffects.createCombatEngine({rules:Rules,rng:rng([1])});const result=engine.cast(state,{actorId:'player',ability:{id:'fatal',apCost:0,range:{min:1,max:1},targeting:{targetType:'ENEMY',shape:'SINGLE'},effects:[{type:'DAMAGE',target:'TARGET',damageType:'PHYSICAL',amount:999}]},target:{x:1,y:0}});assert(result.ok);assert.equal(boss.hp,1);assert(result.events.some(e=>e.type===CombatEffects.EVENT_TYPES.BOSS_CRITICAL));assert.equal(result.events.some(e=>e.type===CombatEffects.EVENT_TYPES.UNIT_DIED),false);});
test('CombatEffectEngine still emits UNIT_DIED for ordinary mobs',()=>{const mob={id:'mob',side:'mob',x:1,y:0,hp:10,maxHp:10,pa:0,pm:0,cooldowns:{},effects:[],resistances:{PHYSICAL:0,MAGICAL:0},combatStats:{}};const player={id:'player',side:'player',x:0,y:0,hp:100,maxHp:100,pa:6,pm:4,maxPa:6,maxPm:4,cooldowns:{},effects:[],resistances:{PHYSICAL:0,MAGICAL:0},combatStats:{}};const state={board:Array.from({length:2},()=>Array(2).fill('empty')),combatants:[player,mob],eventSequence:0};const engine=CombatEffects.createCombatEngine({rules:Rules,rng:rng([1])});const result=engine.cast(state,{actorId:'player',ability:{id:'fatal',apCost:0,range:{min:1,max:1},targeting:{targetType:'ENEMY',shape:'SINGLE'},effects:[{type:'DAMAGE',target:'TARGET',damageType:'PHYSICAL',amount:999}]},target:{x:1,y:0}});assert(result.events.some(e=>e.type===CombatEffects.EVENT_TYPES.UNIT_DIED));assert.equal(mob.hp,0);});
test('Sineira strategy is deterministic for identical turn and crava inputs',()=>{const run=()=>{const encounter=Sineira.createSineiraEncounter({cravas:['A','B']});return [encounter.beginTurn(1),encounter.beginTurn(2),encounter.interactCrava('A'),encounter.interactCrava('B'),encounter.tryResolve()].map(value=>JSON.stringify(value));};assert.deepEqual(run(),run());});
// Mission 10C: narrative closure after a valid non-lethal resolution.
const makeNarrativeFixture=({autoComplete=false}={})=>{const flags={},inventory={},progression={MAIN_06:{state:'COMPLETED',progress:{},seenEvents:{},rewardClaimed:true}};const questDb={MAIN_06:{id:'MAIN_06',prerequisites:[],objectives:[{id:'done',type:'TALK',target:'NPC_MIRA',amount:1}],rewards:{}},MAIN_07:Fimbria.quests.MAIN_07,MAIN_08:Fimbria.quests.MAIN_08};const q=QuestApi.createQuestSystem({questDb,progression,autoComplete,flagProvider:id=>flags[id]===true,inventoryProvider:()=>({inventory})});const w=WorldApi.createWorldState({progressionProvider:()=>({flags}),questSystem:q});const narrative=NarrativeApi.createNarrativeAdapter({questSystem:q,worldState:w,inventoryProvider:()=>({inventory})});return {flags,inventory,q,w,narrative};};
test('MAIN_07 accepts only the correct non-lethal Sineira resolution',()=>{const {flags,q,narrative}=makeNarrativeFixture();assert(q.acceptQuest('MAIN_07'));q.recordEvent({type:'MAP_VISITED',mapId:'MAP_10',eventId:'m10'});q.recordEvent({type:'MAP_VISITED',mapId:'MAP_11',eventId:'m11'});assert.equal(narrative.handleBossResolved({type:'BOSS_RESOLVED',bossId:'OTHER',resolution:'NON_LETHAL',nonLethal:true,eventId:'wrong'}).ok,false);assert.equal(narrative.handleBossResolved({type:'BOSS_RESOLVED',bossId:'CRE_SINEIRA',resolution:'KILLED',nonLethal:false,eventId:'dead'}).ok,false);assert.equal(flags.FLAG_SINEIRA_RESOLVED,undefined);const event={type:'BOSS_RESOLVED',bossId:'CRE_SINEIRA',resolution:'NON_LETHAL',nonLethal:true,eventId:'boss-once'};const valid=narrative.handleBossResolved(event);assert(valid.ok);assert.equal(flags.FLAG_SINEIRA_RESOLVED,true);assert.equal(q.getObjectiveViews('MAIN_07').find(o=>o.id==='main07_sineira').current,1);assert.equal(narrative.handleBossResolved({...event,eventId:'boss-duplicate'}).duplicate,true);});
test('QuestSystem rejects a normal death event for the canonical Sineira objective',()=>{const {q}=makeNarrativeFixture();q.acceptQuest('MAIN_07');q.recordEvent({type:'BOSS_RESOLVED',bossId:'CRE_SINEIRA',eventId:'missing-resolution'});assert.equal(q.getObjectiveViews('MAIN_07').find(o=>o.id==='main07_sineira').current,0);q.recordEvent({type:'UNIT_DIED',bossId:'CRE_SINEIRA',eventId:'death'});assert.equal(q.getObjectiveViews('MAIN_07').find(o=>o.id==='main07_sineira').current,0);});
test('Real Sineira BOSS_RESOLVED callback reaches the narrative adapter',()=>{const {flags,q,narrative}=makeNarrativeFixture();q.acceptQuest('MAIN_07');const encounter=Sineira.createSineiraEncounter({cravas:['A','B'],onEvent:event=>narrative.handleBossResolved(event)});encounter.beginTurn(2);encounter.interactCrava('A');encounter.interactCrava('B');const resolved=encounter.tryResolve();assert(resolved.ok);assert.equal(flags.FLAG_SINEIRA_RESOLVED,true);});
test('Seal inspection is blocked before resolution and enabled afterwards',()=>{const {flags,narrative}=makeNarrativeFixture();assert.equal(narrative.canInspectSeal(),false);assert.equal(narrative.inspectSeal().reason,'SINEIRA_NOT_RESOLVED');flags.FLAG_SINEIRA_RESOLVED=true;assert.equal(narrative.canInspectSeal(),true);});
test('Valid seal inspection emits POINT_INSPECTED, flag and decalque once',()=>{const {flags,inventory,q,narrative}=makeNarrativeFixture();q.acceptQuest('MAIN_07');flags.FLAG_SINEIRA_RESOLVED=true;q.recordEvent({type:'MAP_VISITED',mapId:'MAP_10',eventId:'m10'});q.recordEvent({type:'MAP_VISITED',mapId:'MAP_11',eventId:'m11'});q.recordEvent({type:'BOSS_RESOLVED',bossId:'CRE_SINEIRA',resolution:'NON_LETHAL',nonLethal:true,eventId:'b'});const first=narrative.inspectSeal();assert(first.ok);assert.equal(first.inspection.event.type,'POINT_INSPECTED');assert.equal(flags.FLAG_SEAL_INSPECTED,true);assert.equal(inventory.QITEM_DECALQUE_DO_SELO,1);assert.equal(q.getObjectiveViews('MAIN_07').find(o=>o.id==='main07_seal').current,1);const second=narrative.inspectSeal();assert(second.ok);assert.equal(second.duplicate,true);assert.equal(inventory.QITEM_DECALQUE_DO_SELO,1);});
test('MAIN_07 completes after seal inspection without an invented turn-in',()=>{const {flags,q,narrative}=makeNarrativeFixture();q.acceptQuest('MAIN_07');q.recordEvent({type:'MAP_VISITED',mapId:'MAP_10',eventId:'m10'});q.recordEvent({type:'MAP_VISITED',mapId:'MAP_11',eventId:'m11'});narrative.handleBossResolved({type:'BOSS_RESOLVED',bossId:'CRE_SINEIRA',resolution:'NON_LETHAL',nonLethal:true,eventId:'b'});const result=narrative.inspectSeal();assert(result.main07Completed);assert.equal(q.getQuestState('MAIN_07'),'COMPLETED');});
test('MAIN_08 remains gated until MAIN_07 and both narrative flags are ready',()=>{const flags={},inventory={QITEM_DECALQUE_DO_SELO:1},q=QuestApi.createQuestSystem({questDb:{MAIN_07:Fimbria.quests.MAIN_07,MAIN_08:Fimbria.quests.MAIN_08},progression:{MAIN_07:{state:'COMPLETED',progress:{},seenEvents:{},rewardClaimed:true}},flagProvider:id=>flags[id]===true,inventoryProvider:()=>({inventory})});assert.equal(q.getQuestState('MAIN_08'),'LOCKED');flags.FLAG_SINEIRA_RESOLVED=true;assert.equal(q.getQuestState('MAIN_08'),'LOCKED');flags.FLAG_SEAL_INSPECTED=true;assert.equal(q.getQuestState('MAIN_08'),'AVAILABLE');assert(q.acceptQuest('MAIN_08'));assert.equal(q.getObjectiveViews('MAIN_08').find(o=>o.id==='main08_decalque').current,1);});
test('Decalque is a persistent non-sellable quest item',()=>{const item=ItemData.QITEM_DECALQUE_DO_SELO;assert.equal(item.questItem,true);assert.equal(item.economy.sellable,false);const state=baseSnapshot();state.player.inventory.QITEM_DECALQUE_DO_SELO=1;state.progression.flags={FLAG_SINEIRA_RESOLVED:true,FLAG_SEAL_INSPECTED:true};const storage=new Persistence.MemoryStorageAdapter(),save=Persistence.createSaveSystem({storage,mapDatabase:testMaps,itemDb:ItemData,createInitialPlayerState:Rules.createPlayerState,createInitialWorldState:initialWorld});save.saveNow(state);const loaded=save.load();assert.equal(loaded.player.inventory.QITEM_DECALQUE_DO_SELO,1);assert.equal(loaded.progression.flags.FLAG_SINEIRA_RESOLVED,true);});
test('Narrative metadata preserves Batidas and entalhes as unknown',()=>{assert.equal(Fimbria.mysteries.BATTIDAS.relation,'UNKNOWN');assert.equal(Fimbria.mysteries.SETE_ENTALHES.meaning,'UNKNOWN');assert.equal(Fimbria.bosses.CRE_SINEIRA.identity.alignment,'não maligna');});
// Mission 11A: pure responsive viewport/coordinate contracts.
const viewportRect=(left,top,width,height)=>({left,top,width,height});
test('Viewport maps logical 1:1 canvas cells correctly',()=>{const point=Viewport.screenToGrid({clientX:120,clientY:80,rect:viewportRect(0,0,480,480),logicalWidth:480,logicalHeight:480,gridSize:12});assert(point.ok);assert.deepEqual({x:3,y:2},{x:point.x,y:point.y});});
test('Viewport maps a reduced visual canvas to the same logical cell',()=>{const point=Viewport.screenToGrid({clientX:70,clientY:50,rect:viewportRect(10,10,240,240),logicalWidth:480,logicalHeight:480,gridSize:12});assert.deepEqual({x:3,y:2},{x:point.x,y:point.y});});
test('Viewport maps an enlarged visual canvas to the same logical cell',()=>{const point=Viewport.screenToGrid({clientX:300,clientY:220,rect:viewportRect(50,40,960,960),logicalWidth:480,logicalHeight:480,gridSize:12});assert.deepEqual({x:3,y:2},{x:point.x,y:point.y});});
test('Viewport honors offsets and canvas borders',()=>{const point=Viewport.screenToGrid({clientX:205,clientY:105,rect:viewportRect(5,5,400,400),logicalWidth:400,logicalHeight:400,gridSize:8});assert.deepEqual({x:4,y:2},{x:point.x,y:point.y});});
test('Viewport rejects pointer input outside the displayed canvas',()=>{const rect=viewportRect(20,30,240,240);assert.equal(Viewport.screenToGrid({clientX:19,clientY:100,rect,logicalWidth:480,logicalHeight:480,gridSize:12}).ok,false);assert.equal(Viewport.screenToGrid({clientX:260,clientY:100,rect,logicalWidth:480,logicalHeight:480,gridSize:12}).ok,false);});
test('Viewport keeps grid resolution independent from visual size',()=>{const logical={width:480,height:480,gridSize:12};const a=Viewport.screenToGrid({clientX:140,clientY:140,rect:viewportRect(20,20,240,240),logicalWidth:logical.width,logicalHeight:logical.height,gridSize:logical.gridSize});const b=Viewport.screenToGrid({clientX:580,clientY:580,rect:viewportRect(100,100,960,960),logicalWidth:logical.width,logicalHeight:logical.height,gridSize:logical.gridSize});assert.equal(a.x,b.x);assert.equal(a.y,b.y);assert.equal(logical.gridSize,12);});
test('Viewport rejects invalid pointer or zero-size rectangles safely',()=>{assert.equal(Viewport.screenToGrid({clientX:undefined,clientY:1,rect:viewportRect(0,0,100,100),logicalWidth:480,logicalHeight:480,gridSize:12}).ok,false);assert.equal(Viewport.screenToGrid({clientX:1,clientY:1,rect:viewportRect(0,0,0,100),logicalWidth:480,logicalHeight:480,gridSize:12}).ok,false);assert.equal(Viewport.screenToGrid({clientX:1,clientY:1,rect:null,logicalWidth:480,logicalHeight:480,gridSize:12}).ok,false);});
// Mission 11B: pure HUD/feedback presentation contracts.
test('UI feedback translates known reasons and safely falls back',()=>{assert.equal(UiFeedback.reasonMessage('PA'),'PA insuficiente.');assert.equal(UiFeedback.reasonMessage('UNKNOWN'),'Ação indisponível.');});
test('UI feedback translates combat and boss events without changing state',()=>{assert.equal(UiFeedback.eventMessage({type:'DAMAGE_APPLIED',amount:12},'Sineira'),'Sineira sofreu 12 dano.');assert.equal(UiFeedback.eventMessage({type:'BOSS_CRITICAL'},'Sineira'),'Sineira chegou ao estado crítico, mas permanece vivo.');assert.equal(UiFeedback.eventMessage({type:'BOSS_RESOLVED'},'Sineira'),'Sineira foi resolvida sem morte.');});
test('Pending telegraphs become highlight cells while resolved/cancelled do not',()=>{const cells=UiFeedback.activeTelegraphCells([{id:'p',status:'PENDING',target:{x:2,y:3}},{id:'r',status:'RESOLVED',target:{x:4,y:4}},{id:'c',status:'CANCELLED',area:{cells:[{x:5,y:5}]}},{id:'a',status:'PENDING',area:{cells:[{x:6,y:6},{x:7,y:6}]}}]);assert.deepEqual(cells.map(c=>[c.x,c.y]),[[2,3],[6,6],[7,6]]);});
test('Quest display labels preserve progress and completion semantics',()=>{assert.equal(UiFeedback.objectiveLabel({type:'KILL'}),'Derrotar');assert.equal(UiFeedback.objectiveLabel({type:'INSPECT'}),'Inspecionar');assert.equal(UiFeedback.objectiveLabel({type:'UNKNOWN'}),'Objetivo');});
test('Unknown UI events and malformed telegraphs fail safely',()=>{assert.equal(UiFeedback.eventMessage({type:'UNKNOWN_EVENT'}),null);assert.deepEqual(UiFeedback.activeTelegraphCells([null,{}, {status:'PENDING',target:{x:'bad',y:2}},{status:'PENDING',area:{cells:[null,{x:1,y:1},{x:'bad',y:2}]}}]),[{x:1,y:1,telegraphId:undefined}]);});
// Mission 12: offline command/result boundary over the existing engines.
test('Command contract accepts stable JSON-safe commands and round-trips',()=>{const command=Commands.createCommand({id:'cmd-1',type:Commands.COMMAND_TYPES.MOVE,actorId:'player',payload:{x:2,y:3},clientSequence:7});assert(command);assert.deepEqual(JSON.parse(JSON.stringify(command)),command);assert.equal(Commands.validateCommand(command).ok,true);});
test('Command contract rejects unknown types, malformed payloads and non-serializable values',()=>{assert.equal(Commands.createCommand({id:'bad',type:'UNKNOWN',actorId:'player',payload:{}}),null);assert.equal(Commands.createCommand({id:'bad-move',type:'MOVE',actorId:'player',payload:{x:'2',y:3}}),null);const circular={};circular.self=circular;assert.equal(Commands.validateCommand({id:'circular',type:Commands.COMMAND_TYPES.INTERACT,actorId:'player',payload:{targetId:'x',circular}}).ok,false);});
test('Command types remain minimal and explicit',()=>{assert.deepEqual(Object.values(Commands.COMMAND_TYPES),['MOVE','CAST_ABILITY','INTERACT','END_TURN']);});
const authorityState=()=>({board:[['empty','empty'],['empty','empty']],combatants:[{id:'player',side:'player',x:0,y:0,hp:100,maxHp:100,pa:6,maxPa:6,pm:4,maxPm:4,cooldowns:{},effects:[],resistances:{PHYSICAL:0,MAGICAL:0},combatStats:{forca:0}},{id:'mob',side:'mob',x:1,y:0,hp:100,maxHp:100,pa:0,maxPa:0,pm:0,maxPm:0,cooldowns:{},effects:[],resistances:{PHYSICAL:0,MAGICAL:0},combatStats:{}}],eventSequence:0});
