test('Ability preview Cruz separates targetable cells from affected AoE cells',()=>{const actor=previewActor(),state=previewState([actor]),engine=previewEngine(),preview=AbilityPreview.preview({state,actor,ability:Abilities.cruz,engine,hoverCell:{x:3,y:4}});assert(preview.targetableCells.length>preview.affectedCells.length);assert(preview.targetableCells.some(cell=>cell.x===3&&cell.y===4));assert(preview.affectedCells.some(cell=>cell.x===3&&cell.y===4));});
