test('Ability preview targetable cells and engine validation remain consistent on the logical grid',()=>{const actor=previewActor(),enemy={id:'enemy',side:'mob',x:3,y:1,hp:100,maxHp:100,pa:0,pm:0,cooldowns:{},effects:[],resistances:{PHYSICAL:0,MAGICAL:0},combatStats:{}},state=previewState([actor,enemy]),engine=previewEngine();[Abilities.golpe,Abilities.avanco,Abilities.cruz,Abilities.lanca].forEach(ability=>{const keys=new Set(AbilityPreview.getTargetableCells({state,actor,ability,engine}).map(cellKey));for(let y=0;y<state.board.length;y++)for(let x=0;x<state.board.length;x++){const accepted=engine.validate(state,actor,ability,{x,y}).ok;assert.equal(keys.has(`${x},${y}`),accepted,`${ability.id} diverged at ${x},${y}`);}});assert.deepEqual(AbilityPreview.getTargetableCells({state,actor,ability:Abilities.fortificar,engine}),[{x:actor.x,y:actor.y}]);});
// Mission 13: deterministic cross-system contracts for the frozen V1 feature set.
test('M13 new game flows from Mira quest through combat death, reward and reload once',()=>{const state=baseSnapshot(),storage=new Persistence.MemoryStorageAdapter(),player=state.player;let rewards=0;const quests=QuestApi.createQuestSystem({questDb:QuestData,progression:state.progression.quests,autoComplete:false,rewardSink:reward=>{rewards++;Rules.grantXp(player,reward.xp||0);Rules.addLoot(player,(reward.items||[]).map(item=>({id:item.itemId,qty:item.amount})));}}),npcs=makeNpcEngine(quests,state.world.player);assert.equal(player.playerId,'player');assert(npcs.execute('guarda_mira',{id:'accept_quest',questId:'primeira_batalha'}).ok);const actor={id:'player',side:'player',x:0,y:0,hp:100,maxHp:100,pa:6,maxPa:6,pm:4,maxPm:4,cooldowns:{},effects:[],resistances:{PHYSICAL:0,MAGICAL:0},combatStats:{forca:0}},mob={id:'enc-javali',mobId:'enc-javali',mobType:'javali',side:'mob',x:1,y:0,hp:10,maxHp:10,pa:0,maxPa:0,pm:0,maxPm:0,cooldowns:{},effects:[],resistances:{PHYSICAL:0,MAGICAL:0},combatStats:{}},combat={board:[['empty','empty'],['empty','empty']],combatants:[actor,mob],eventSequence:0},engine=CombatEffects.createCombatEngine({rules:Rules,rng:rng([0])}),cast=engine.cast(combat,{actorId:'player',ability:Abilities.golpe,target:{x:1,y:0}}),death=cast.events.find(event=>event.type===CombatEffects.EVENT_TYPES.UNIT_DIED);assert(cast.ok&&death);quests.recordEvent({type:'MOB_KILLED',mobType:mob.mobType,eventId:death.id});quests.recordEvent({type:'MOB_KILLED',mobType:mob.mobType,eventId:death.id});assert(quests.isComplete('primeira_batalha'));assert(npcs.execute('guarda_mira',{id:'deliver_quest',questId:'primeira_batalha'}).ok);assert.equal(rewards,1);assert.equal(player.xp,35);assert.equal(player.inventory.pocao_simples,1);state.combat=combat;const saved=makePersistence(storage,state).saveNow(),loaded=makePersistence(storage).load();assert.equal(saved.combat,undefined);assert.equal(loaded.progression.quests.primeira_batalha.state,'COMPLETED');assert.equal(loaded.player.inventory.pocao_simples,1);});
test('M13 consumable, equipment, economy and persistence preserve one rich durable projection',()=>{const player=Rules.createPlayerState(),progression={quests:{q:{state:'ACTIVE',progress:{},seenEvents:{},rewardClaimed:false}},currency:{base:30},flags:{FLAG_TEST:true}},state={player,world:initialWorld(),progression,authority:{stateVersion:9}},storage=new Persistence.MemoryStorageAdapter();player.hp=60;player.inventory.pocao_simples=1;const consumables=ConsumableApi.createConsumableSystem({itemDb:ItemData,playerProvider:()=>player,inventoryProvider:()=>player});assert.equal(consumables.use('pocao_simples').healed,30);player.inventory.chapeu_couro=1;player.equipment.hat='chapeu_couro';delete player.inventory.chapeu_couro;Rules.clampPlayerHp(player,ItemData);assert.equal(player.maxHp,120);const economy=EconomyApi.createEconomySystem({playerProvider:()=>player,progressionProvider:()=>progression,itemDb:ItemData,catalog:{pocao_simples:{itemId:'pocao_simples',buyPrice:12,sellPrice:6,sellable:true}}});assert(economy.buy('pocao_simples').ok);assert(economy.sell('pocao_simples').ok);assert.equal(economy.getBalance(),24);const before=JSON.stringify({inventory:player.inventory,currency:progression.currency});assert.equal(economy.buy('missing').ok,false);assert.equal(JSON.stringify({inventory:player.inventory,currency:progression.currency}),before);const save=makeFullPersistence(storage,state),payload=save.saveNow(),loaded=makeFullPersistence(storage).load();assert.equal(payload.version,2);assert.equal(payload.authority,undefined);assert.equal(loaded.player.equipment.hat,'chapeu_couro');assert.equal(loaded.player.maxHp,120);assert.equal(loaded.progression.currency.base,24);assert.equal(loaded.progression.flags.FLAG_TEST,true);});
test('M13 authority turn flow applies cast/status once and ends the turn through the engine',()=>{const actor={id:'player',side:'player',x:0,y:0,hp:100,maxHp:100,pa:6,maxPa:6,pm:4,maxPm:4,cooldowns:{},effects:[],resistances:{PHYSICAL:0,MAGICAL:0},combatStats:{forca:0}},mob={id:'mob',side:'mob',x:2,y:0,hp:100,maxHp:100,pa:0,maxPa:0,pm:0,maxPm:0,cooldowns:{},effects:[],resistances:{PHYSICAL:0,MAGICAL:0},combatStats:{}},state={board:Array.from({length:3},()=>Array(3).fill('empty')),combatants:[actor,mob],eventSequence:0},engine=CombatEffects.createCombatEngine({rules:Rules,rng:rng([0])}),authority=AuthorityApi.createLocalAuthority({combatEngine:engine,stateProvider:()=>state,abilityProvider:id=>Abilities[id]}),castCommand=Commands.createCommand({id:'m13-cast',type:'CAST_ABILITY',actorId:'player',payload:{abilityId:'lanca',target:{x:2,y:0}}}),first=authority.dispatch(castCommand),hpAfterCast=mob.hp,duplicate=authority.dispatch(JSON.parse(JSON.stringify(castCommand)));assert(first.accepted&&first.events.some(event=>event.type===CombatEffects.EVENT_TYPES.STATUS_APPLIED));assert.deepEqual(duplicate,first);assert.equal(mob.hp,hpAfterCast);const start=engine.startTurn(state,'mob');assert(start.events.some(event=>event.type===CombatEffects.EVENT_TYPES.DAMAGE_APPLIED));const end=authority.dispatch(Commands.createCommand({id:'m13-end',type:'END_TURN',actorId:'player',payload:{}}));assert(end.accepted&&end.events.some(event=>event.type===CombatEffects.EVENT_TYPES.TURN_ENDED));assert.equal(authority.stateVersion,2);assert.deepEqual(JSON.parse(JSON.stringify(end)),end);});
