test('M13 Sineira non-lethal resolution reaches seal narrative, MAIN_07 and persistence once',()=>{const {flags,inventory,q,narrative}=makeNarrativeFixture();assert(q.acceptQuest('MAIN_07'));q.recordEvent({type:'MAP_VISITED',mapId:'MAP_10',eventId:'m10'});q.recordEvent({type:'MAP_VISITED',mapId:'MAP_11',eventId:'m11'});const encounter=Sineira.createSineiraEncounter({cravas:['A','B'],onEvent:event=>narrative.handleBossResolved(event)});assert.equal(encounter.beginTurn(1).phase,'GUARDIA');const planned=encounter.planAction({actionId:'SINEIRA_BATIDA',target:{x:1,y:0}});assert(planned.ok);assert.equal(encounter.beginTurn(2).phase,'ALVOROCO');assert(encounter.resolveAction(planned.telegraph.id).ok);const critical=encounter.applyIncomingDamage(999);assert.equal(critical.death,false);assert.equal(encounter.boss.snapshot().state,'CRITICAL');assert(encounter.interactCrava('A').ok);assert(encounter.interactCrava('B').ok);const resolved=encounter.tryResolve();assert(resolved.ok&&resolved.event.nonLethal);assert.equal(flags.FLAG_SINEIRA_RESOLVED,true);const seal=narrative.inspectSeal();assert(seal.ok&&seal.main07Completed);assert.equal(inventory.QITEM_DECALQUE_DO_SELO,1);assert(narrative.inspectSeal().duplicate);const player=Rules.createPlayerState();player.inventory=inventory;const storage=new Persistence.MemoryStorageAdapter(),save=makeFullPersistence(storage,{player,world:initialWorld(),progression:{quests:q.progression,currency:{},flags}});save.saveNow();const loaded=save.load();assert.equal(loaded.player.inventory.QITEM_DECALQUE_DO_SELO,1);assert.equal(loaded.progression.flags.FLAG_SEAL_INSPECTED,true);});
test('M13 preview preserves rectangular logical board bounds without changing combat geometry',()=>{const actor={...previewActor(),x:2,y:1},state={board:Array.from({length:3},()=>Array(5).fill('empty')),combatants:[actor],eventSequence:0},engine=previewEngine(),affected=AbilityPreview.getAffectedCells({state,actor,ability:Abilities.cruz,engine,cell:{x:3,y:1}});assert(affected.some(cell=>cell.x===4&&cell.y===1));assert.equal(affected.some(cell=>cell.x===3&&cell.y===3),false);});
test('M13 canonical chain and runtime identities remain valid without alias collisions',()=>{assert(Fimbria.validateReferences().ok);assert.deepEqual(Object.keys(Fimbria.quests).filter(id=>id.startsWith('MAIN_')).sort(),['MAIN_01','MAIN_02','MAIN_03','MAIN_04','MAIN_05','MAIN_06','MAIN_07','MAIN_08']);const ids=[...Object.keys(Fimbria.creatures),...Object.keys(Fimbria.maps),...Object.keys(Fimbria.encounters),...Object.keys(Fimbria.quests)];assert.equal(ids.filter(id=>id.includes('_')).length,ids.length);assert.equal(new Set(FimbriaRuntime.normalCreatureIds).size,FimbriaRuntime.normalCreatureIds.length);});
