// Visual V1: projection is pure presentation geometry over the existing logical grid.
const isoProjection={tileWidth:40,tileHeight:20,originX:100,originY:100};
test('Visual V1 gridToScreen maps origin and both logical axes into a diamond projection',()=>{assert.deepEqual(Isometric.gridToScreen({x:0,y:0,projection:isoProjection}),{x:100,y:100});assert.deepEqual(Isometric.gridToScreen({x:1,y:0,projection:isoProjection}),{x:120,y:110});assert.deepEqual(Isometric.gridToScreen({x:0,y:1,projection:isoProjection}),{x:80,y:110});assert.deepEqual(Isometric.gridToScreen({x:3,y:2,projection:isoProjection}),{x:120,y:150});});
test('Visual V1 screenToGrid recovers logical centers across the board',()=>{[[0,0],[1,0],[0,1],[3,2],[11,11]].forEach(([x,y])=>{const center=Isometric.gridToScreen({x,y,projection:isoProjection}),picked=Isometric.screenToGrid({screenX:center.x,screenY:center.y,projection:isoProjection,bounds:{columns:12,rows:12}});assert.deepEqual(picked,{ok:true,x,y});});});
test('Visual V1 grid screen round-trip preserves corners, edges and intermediate cells',()=>{const projection=Isometric.centeredConfig({canvasWidth:480,canvasHeight:480,columns:12,rows:12,tileWidth:36,tileHeight:18});[[0,0],[11,0],[0,11],[11,11],[2,10],[6,6]].forEach(([x,y])=>{const screen=Isometric.gridToScreen({x,y,projection}),grid=Isometric.screenToGrid({screenX:screen.x,screenY:screen.y,projection,bounds:{columns:12,rows:12}});assert.deepEqual(grid,{ok:true,x,y});});});
test('Visual V1 diamond picking accepts inner edge points and rejects board exterior',()=>{const center=Isometric.gridToScreen({x:2,y:3,projection:isoProjection});assert.deepEqual(Isometric.screenToGrid({screenX:center.x+7,screenY:center.y+3,projection:isoProjection,bounds:{columns:12,rows:12}}),{ok:true,x:2,y:3});assert.deepEqual(Isometric.screenToGrid({screenX:center.x-7,screenY:center.y-3,projection:isoProjection,bounds:{columns:12,rows:12}}),{ok:true,x:2,y:3});assert.equal(Isometric.screenToGrid({screenX:100,screenY:89,projection:isoProjection,bounds:{columns:12,rows:12}}).ok,false);});
test('Visual V1 projection configuration changes visual placement without changing picked cell',()=>{const alternate={tileWidth:56,tileHeight:28,originX:312,originY:81};const screen=Isometric.gridToScreen({x:4,y:7,projection:alternate});assert.notDeepEqual(screen,Isometric.gridToScreen({x:4,y:7,projection:isoProjection}));assert.deepEqual(Isometric.screenToGrid({screenX:screen.x,screenY:screen.y,projection:alternate,bounds:{columns:12,rows:12}}),{ok:true,x:4,y:7});});
test('Visual V1 depth order is deterministic and derived only from logical placement',()=>{const ordered=[{id:'back',x:0,y:3},{id:'front',x:1,y:1},{id:'middle',x:1,y:0}].sort(Isometric.depthCompare);assert.deepEqual(ordered.map(entry=>entry.id),['middle','front','back']);});
test('V8-FIX-OW-A overworld depth ties render scenery before entities deterministically',()=>{const sameCell=[{id:'player',kind:'player',x:4,y:3},{id:'house',kind:'visual-prop',x:4,y:3},{id:'wall',kind:'obstacle',x:4,y:3},{id:'npc:z',kind:'npc',x:4,y:3},{id:'mob:z',kind:'mob',x:4,y:3}].sort(Isometric.overworldDepthCompare);assert.deepEqual(sameCell.map(entry=>entry.kind),['obstacle','visual-prop','mob','npc','player']);const front=[{id:'actor',kind:'player',x:2,y:2},{id:'tree',kind:'obstacle',x:1,y:2}].sort(Isometric.overworldDepthCompare);assert.deepEqual(front.map(entry=>entry.id),['tree','actor']);});
test('V8-FIX-OW-A applies its tie-breaker only to overworld and leaves combat painter ordering unchanged',()=>{const source=fs.readFileSync(path.join(__dirname,'..','main.js'),'utf8'),overworld=source.slice(source.indexOf('function renderOverworldFrame'),source.indexOf('function drawOverworldToken')),combat=source.slice(source.indexOf('  const scene=[];',source.indexOf('function renderOverworldFrame')+1),source.indexOf('function projectedCellCenter'));assert(overworld.includes('scene.sort(Isometric.overworldDepthCompare)'));assert(combat.includes('scene.sort(Isometric.depthCompare)'));});
