// Visual V2: overworld reuses the same projection for variable map dimensions.
const rectangularOverworldProjection=Isometric.fitProjection({canvasWidth:480,canvasHeight:480,columns:24,rows:18,preferredTileWidth:54,preferredTileHeight:27,padding:24});
test('Visual V2 fits and centers a rectangular 24 by 18 overworld projection',()=>{const p=rectangularOverworldProjection,corners=[[0,0],[23,0],[0,17],[23,17]].map(([x,y])=>Isometric.gridToScreen({x,y,projection:p}));const minX=Math.min(...corners.map(cell=>cell.x-p.tileWidth/2)),maxX=Math.max(...corners.map(cell=>cell.x+p.tileWidth/2)),minY=Math.min(...corners.map(cell=>cell.y-p.tileHeight/2)),maxY=Math.max(...corners.map(cell=>cell.y+p.tileHeight/2));assert.equal(p.columns,24);assert.equal(p.rows,18);assert(p.scale<1);assert.equal(p.tileWidth/p.tileHeight,2);assert(minX>=24-1e-9&&maxX<=456+1e-9);assert(minY>=24-1e-9&&maxY<=456+1e-9);});
test('Visual V2 rectangular overworld projection round-trips first, last and internal cells',()=>{[[0,0],[23,0],[0,17],[23,17],[9,7]].forEach(([x,y])=>{const screen=Isometric.gridToScreen({x,y,projection:rectangularOverworldProjection}),picked=Isometric.screenToGrid({screenX:screen.x,screenY:screen.y,projection:rectangularOverworldProjection,bounds:{columns:24,rows:18}});assert.deepEqual(picked,{ok:true,x,y});});});
test('V8-UIC fit zoom grows with a larger rectangular presentation viewport',()=>{const small=Isometric.fitProjection({canvasWidth:480,canvasHeight:480,columns:12,rows:10,preferredTileWidth:54,preferredTileHeight:27,padding:18}),large=Isometric.fitProjection({canvasWidth:1000,canvasHeight:700,columns:12,rows:10,preferredTileWidth:54,preferredTileHeight:27,padding:18});assert(large.scale>small.scale);assert(large.tileWidth>small.tileWidth);assert.deepEqual([small.columns,small.rows,large.columns,large.rows],[12,10,12,10]);});
test('V8-UIC rectangular MAP_01 to MAP_11 projections fit tile bounds and preserve screen-to-grid picking',()=>{MapVisuals.forEach(layout=>{const {width:columns,height:rows}=layout.dimensions,logicalWidth=960,logicalHeight=620,projection=Isometric.fitProjection({canvasWidth:logicalWidth,canvasHeight:logicalHeight,columns,rows,preferredTileWidth:72,preferredTileHeight:36,padding:24}),corners=[[0,0],[columns-1,0],[0,rows-1],[columns-1,rows-1]].map(([x,y])=>Isometric.gridToScreen({x,y,projection})),xs=corners.map(point=>point.x),ys=corners.map(point=>point.y);assert(Math.min(...xs)-projection.tileWidth/2>=24-1e-9,`${layout.mapId} left bound`);assert(Math.max(...xs)+projection.tileWidth/2<=936+1e-9,`${layout.mapId} right bound`);assert(Math.min(...ys)-projection.tileHeight/2>=24-1e-9,`${layout.mapId} top bound`);assert(Math.max(...ys)+projection.tileHeight/2<=596+1e-9,`${layout.mapId} bottom bound`);const rect={left:20,top:30,width:720,height:465};[[0,0],[columns-1,0],[0,rows-1],[columns-1,rows-1],[Math.floor(columns/2),Math.floor(rows/2)]].forEach(([x,y])=>{const point=Isometric.gridToScreen({x,y,projection}),canvasPoint=Viewport.screenToCanvas({clientX:rect.left+point.x*rect.width/logicalWidth,clientY:rect.top+point.y*rect.height/logicalHeight,rect,logicalWidth,logicalHeight});assert(canvasPoint.ok);assert.deepEqual(Isometric.screenToGrid({screenX:canvasPoint.logicalX,screenY:canvasPoint.logicalY,projection,bounds:{columns,rows}}),{ok:true,x,y});});});});
test('V8-UIC combat keeps a 12 by 12 logical board and preserves scaled-screen picking in a wide view',()=>{const columns=12,rows=12,logicalWidth=1100,logicalHeight=680,projection=Isometric.fitProjection({canvasWidth:logicalWidth,canvasHeight:logicalHeight,columns,rows,preferredTileWidth:72,preferredTileHeight:36,padding:24}),rect={left:12,top:16,width:880,height:544};assert.deepEqual([projection.columns,projection.rows],[12,12]);[[0,0],[11,0],[0,11],[11,11],[6,6]].forEach(([x,y])=>{const point=Isometric.gridToScreen({x,y,projection}),canvasPoint=Viewport.screenToCanvas({clientX:rect.left+point.x*rect.width/logicalWidth,clientY:rect.top+point.y*rect.height/logicalHeight,rect,logicalWidth,logicalHeight});assert(canvasPoint.ok);assert.deepEqual(Isometric.screenToGrid({screenX:canvasPoint.logicalX,screenY:canvasPoint.logicalY,projection,bounds:{columns,rows}}),{ok:true,x,y});});});
test('V8-UIC leaves compact map geometry and Save V2 unchanged',()=>{const expected={MAP_01:[12,10],MAP_02:[12,9],MAP_03:[9,8],MAP_04:[12,9],MAP_05:[10,9],MAP_06:[11,9],MAP_07:[12,10],MAP_08:[10,8],MAP_09:[9,8],MAP_10:[10,9],MAP_11:[12,10]};assert.equal(Persistence.SAVE_VERSION,2);assert.deepEqual(Object.keys(FimbriaRuntime.mapDatabase).sort(),Object.keys(expected).sort());Object.entries(expected).forEach(([id,[width,height]])=>assert.deepEqual([FimbriaRuntime.resolveMap(id).width,FimbriaRuntime.resolveMap(id).height],[width,height]));});
test('V8-FIX-OW-A uses consistent overworld tile scale while preserving each map centered bounds, offset and picking',()=>{const view={width:960,height:620},padding=Math.max(12,Math.min(view.width,view.height)*.07),offsetY=padding*.3,referenceColumns=Math.max(...MapVisuals.map(layout=>layout.dimensions.width)),referenceRows=Math.max(...MapVisuals.map(layout=>layout.dimensions.height)),scales=new Set();MapVisuals.forEach(layout=>{const {width:columns,height:rows}=layout.dimensions,projection=Isometric.fitProjectionWithReferenceBounds({canvasWidth:view.width,canvasHeight:view.height,columns,rows,referenceColumns,referenceRows,preferredTileWidth:54,preferredTileHeight:27,padding});projection.originY+=offsetY;scales.add(projection.scale);const points=[[0,0],[columns-1,0],[0,rows-1],[columns-1,rows-1],[Math.floor(columns/2),Math.floor(rows/2)]].map(([x,y])=>({x,y,screen:Isometric.gridToScreen({x,y,projection})})),xs=points.map(entry=>entry.screen.x),ys=points.map(entry=>entry.screen.y);assert(Math.min(...xs)-projection.tileWidth/2>=0);assert(Math.max(...xs)+projection.tileWidth/2<=view.width);assert(Math.min(...ys)-projection.tileHeight/2>=0);assert(Math.max(...ys)+projection.tileHeight/2<=view.height);points.forEach(({x,y,screen})=>assert.deepEqual(Isometric.screenToGrid({screenX:screen.x,screenY:screen.y,projection,bounds:{columns,rows}}),{ok:true,x,y}));});assert.equal(scales.size,1);});
test('V8-UIC.1 combat projection retains its current 12 by 12 fit without overworld offset',()=>{const source=fs.readFileSync(path.join(__dirname,'..','main.js'),'utf8'),combatSection=source.slice(source.indexOf('let combatProjection ='),source.indexOf('let game = null;'));assert(combatSection.includes('columns:COMBAT_GRID_SIZE,rows:COMBAT_GRID_SIZE'));assert(combatSection.includes('preferredTileWidth:72,preferredTileHeight:36'));assert.equal(combatSection.includes('originY+='),false);});
test('Visual V2 rectangular bounds reject outside cells without changing logical dimensions',()=>{const p=rectangularOverworldProjection;assert.equal(Isometric.screenToGrid({screenX:0,screenY:0,projection:p,bounds:{columns:24,rows:18}}).ok,false);const edge=Isometric.gridToScreen({x:23,y:17,projection:p});assert.deepEqual(Isometric.screenToGrid({screenX:edge.x,screenY:edge.y,projection:p,bounds:{columns:24,rows:18}}),{ok:true,x:23,y:17});});
test('Visual V2 overworld and combat preserve the same logical axis orientation',()=>{const combat=Isometric.centeredConfig({canvasWidth:480,canvasHeight:480,columns:12,rows:12,tileWidth:36,tileHeight:18}),overworld=Isometric.fitProjection({canvasWidth:480,canvasHeight:480,columns:8,rows:8,preferredTileWidth:54,preferredTileHeight:27,padding:24});[combat,overworld].forEach(projection=>{const origin=Isometric.gridToScreen({x:2,y:2,projection}),plusX=Isometric.gridToScreen({x:3,y:2,projection}),plusY=Isometric.gridToScreen({x:2,y:3,projection});assert(plusX.x>origin.x&&plusX.y>origin.y);assert(plusY.x<origin.x&&plusY.y>origin.y);});});
test('Visual V2 canvas pipeline maps scaled pointer coordinates into a rectangular overworld cell',()=>{const p=rectangularOverworldProjection,target=Isometric.gridToScreen({x:9,y:7,projection:p}),rect=viewportRect(20,30,240,240),point=Viewport.screenToCanvas({clientX:20+target.x/2,clientY:30+target.y/2,rect,logicalWidth:480,logicalHeight:480}),picked=Isometric.screenToGrid({screenX:point.logicalX,screenY:point.logicalY,projection:p,bounds:{columns:24,rows:18}});assert(point.ok);assert.deepEqual(picked,{ok:true,x:9,y:7});});
// Visual V3: canonical maps become navigable logical runtime maps, independent of rendering.
const compactMapDimensions={MAP_01:[12,10],MAP_02:[12,9],MAP_03:[9,8],MAP_04:[12,9],MAP_05:[10,9],MAP_06:[11,9],MAP_07:[12,10],MAP_08:[10,8],MAP_09:[9,8],MAP_10:[10,9],MAP_11:[12,10]};
test('Visual V4.5 MAP_01 through MAP_11 resolve once with compact canonical dimensions',()=>{assert(FimbriaRuntime.validateMapRegistry().ok);assert.deepEqual(Object.keys(FimbriaRuntime.mapDatabase).sort(),Object.keys(compactMapDimensions).sort());Object.entries(compactMapDimensions).forEach(([id,[width,height]])=>{const map=FimbriaRuntime.resolveMap(id);assert(map&&map.width===width&&map.height===height);assert.equal(map.terrainRows.length,height);assert(map.terrainRows.every(row=>row.length===width));});});
test('Visual V3 every runtime map has a valid spawn and every implemented exit has a valid destination',()=>{Object.values(FimbriaRuntime.mapDatabase).forEach(map=>{assert(Object.keys(map.spawns).length>0);Object.values(map.spawns).forEach(position=>assert(FimbriaRuntime.isWalkable(map.id,position)));map.exits.forEach(exit=>{assert(FimbriaRuntime.isWalkable(map.id,exit));assert(FimbriaRuntime.resolveMap(exit.to));assert(FimbriaRuntime.resolveSpawn(exit.to,exit.targetSpawnId));});});});
test('Visual V3 MAP_01 and MAP_02 transition atomically in both explicit directions',()=>{const outbound=FimbriaRuntime.prepareTransition({mapId:'MAP_01',exitId:'EXIT_MAP01_MAP02'});assert(outbound.ok);assert.equal(outbound.targetMapId,'MAP_02');assert(FimbriaRuntime.isWalkable(outbound.targetMapId,outbound.targetPosition));const returned=FimbriaRuntime.prepareTransition({mapId:outbound.targetMapId,exitId:'EXIT_MAP02_MAP01'});assert(returned.ok);assert.equal(returned.targetMapId,'MAP_01');assert(FimbriaRuntime.isWalkable(returned.targetMapId,returned.targetPosition));});
test('Visual V3 EXIT_CARROCAL remains an always-open sandbox connection',()=>{const open=FimbriaRuntime.prepareTransition({mapId:'MAP_01',exitId:'EXIT_CARROCAL'});assert(open.ok);assert.equal(open.targetMapId,'MAP_04');assert.equal(open.exitId,'EXIT_CARROCAL');});
test('Visual V3 preserves topology marked TBD instead of inventing runtime exits',()=>{assert.equal(FimbriaRuntime.resolveMap('MAP_03').exits.length,0);assert.equal(FimbriaRuntime.resolveMap('MAP_09').exits.length,0);assert.equal(FimbriaRuntime.resolveMap('MAP_06').exits.some(exit=>exit.to==='MAP_07'),false);assert.equal(FimbriaRuntime.resolveMap('MAP_07').exits.some(exit=>exit.to==='MAP_09'),false);});
test('Visual V3 transition persists canonical map and logical spawn in Save V2 while normalizing legacy map IDs',()=>{const storage=new Persistence.MemoryStorageAdapter(),initial=()=>({currentMapId:'MAP_01',player:FimbriaRuntime.resolveSpawn('MAP_01'),mapRuntime:{},moving:false,moveInterval:null,currentEncounterMobIds:null,pendingReturn:null}),save=Persistence.createSaveSystem({storage,mapDatabase:FimbriaRuntime.mapDatabase,itemDb:ItemData,createInitialPlayerState:Rules.createPlayerState,createInitialWorldState:initial,normalizeMapId:FimbriaRuntime.normalizeMapId}),transition=FimbriaRuntime.prepareTransition({mapId:'MAP_01',exitId:'EXIT_MAP01_MAP02'}),state={player:Rules.createPlayerState(),world:{...initial(),currentMapId:transition.targetMapId,player:transition.targetPosition},progression:{quests:{},currency:{},flags:{}}};save.saveNow(state);const loaded=save.load();assert.equal(loaded.world.currentMapId,'MAP_02');assert.deepEqual(loaded.world.player,transition.targetPosition);storage.value=JSON.stringify({...save.serialize(state),world:{currentMapId:'0,0',player:{x:1,y:4}}});assert.equal(save.load().world.currentMapId,'MAP_01');});
test('Visual V4.5 keeps MAP_11 exploration at 12 by 10 and separate from the 12 by 12 combat board',()=>{const map=FimbriaRuntime.resolveMap('MAP_11');assert.deepEqual([map.width,map.height],[12,10]);assert.equal(map.width===12&&map.height===12,false);});
test('Visual V3 map dimensions feed fitProjection without assuming an 8 by 8 overworld',()=>{['MAP_01','MAP_02','MAP_03','MAP_11'].forEach(id=>{const map=FimbriaRuntime.resolveMap(id),projection=Isometric.fitProjection({canvasWidth:480,canvasHeight:480,columns:map.width,rows:map.height,preferredTileWidth:54,preferredTileHeight:27,padding:24}),origin=Isometric.gridToScreen({x:0,y:0,projection}),picked=Isometric.screenToGrid({screenX:origin.x,screenY:origin.y,projection,bounds:{columns:map.width,rows:map.height}});assert.deepEqual(picked,{ok:true,x:0,y:0});});});
