test('Visual V4 manifest paths are local, relative and physically extracted',()=>{const outputRoot=path.resolve(__dirname,'..','..');Object.values(VisualAssets.ASSETS).forEach(asset=>{assert.equal(path.isAbsolute(asset.src),false);assert.equal(/^[A-Za-z]:[\\/]/.test(asset.src),false);assert.equal(asset.src.includes('://'),false);assert(fs.existsSync(path.resolve(outputRoot,asset.src)));});});
test('Visual V4 selected assets retain source package and visual metadata contracts',()=>{const packageIds=new Set(Object.values(VisualAssets.PACKAGES).map(entry=>entry.id));Object.values(VisualAssets.ASSETS).forEach(asset=>{assert(packageIds.has(asset.packageId));assert(asset.anchor.x>=0&&asset.anchor.x<=1);assert(asset.anchor.y>=0&&asset.anchor.y<=1);assert(asset.scale>0&&asset.widthTiles>0);});Object.values(VisualAssets.PACKAGES).forEach(pkg=>assert(fs.existsSync(path.resolve(__dirname,'..','..',pkg.license))));});
test('Visual V4 manifest covers the controlled proof category minimum without loading folders',()=>{const categories=new Set(Object.values(VisualAssets.ASSETS).map(asset=>asset.category));VisualAssets.REQUIRED_CATEGORIES.forEach(category=>assert(categories.has(category)));assert.equal(Object.keys(VisualAssets.ASSETS).length,11);assert.equal(VisualAssets.proofForMap('MAP_02'),Map02Visual);assert.equal(VisualAssets.floorAssetId('MAP_02',0,0),'VIS_GRASS_BASE');});
test('Visual V4 loader caches a safe unavailable state and rejects unknown IDs without gameplay fallback',()=>{let created=0;const loader=AssetLoader.create({manifest:VisualAssets,imageFactory:()=>{created++;return null;}});loader.load('VIS_GRASS_BASE');loader.load('VIS_GRASS_BASE');assert.equal(created,1);assert.equal(loader.status('VIS_GRASS_BASE').state,'unavailable');loader.load('VIS_MISSING');assert.equal(loader.status('VIS_MISSING').state,'missing');assert.equal(loader.draw({drawImage:()=>{throw new Error('must not draw');}},'VIS_GRASS_BASE',{x:0,y:0,projection:{tileWidth:20}}),false);});
test('Visual V4 proof stores logical anchors only and remains compatible with isometric depth order',()=>{const proof=VisualAssets.MAP_01_LAYOUT,projection=Isometric.fitProjection({canvasWidth:480,canvasHeight:480,columns:12,rows:10,preferredTileWidth:54,preferredTileHeight:27,padding:24});proof.props.forEach(prop=>{assert(Number.isInteger(prop.x)&&Number.isInteger(prop.y));assert.equal('screenX' in prop,false);assert.equal('screenY' in prop,false);const point=Isometric.gridToScreen({x:prop.x,y:prop.y,projection});assert(Number.isFinite(point.x)&&Number.isFinite(point.y));});const ordered=[proof.props.find(prop=>prop.id==='map01-tree-01'),{id:'player',x:6,y:5},proof.props.find(prop=>prop.id==='map01-tree-06')].sort(Isometric.depthCompare).map(entry=>entry.id);assert.deepEqual(ordered,['map01-tree-01','player','map01-tree-06']);});
