test('Visual V5A floor overrides, props and blocked cells stay within 12 by 10',()=>{const layout=Map01Visual,inBounds=cell=>Number.isInteger(cell.x)&&Number.isInteger(cell.y)&&cell.x>=0&&cell.x<12&&cell.y>=0&&cell.y<10;layout.floorOverrides.forEach(inBoundsAssert=>assert(inBounds(inBoundsAssert)));layout.props.forEach(prop=>assert(inBounds(prop)));layout.blockedCells.forEach(inBoundsAssert=>assert(inBounds(inBoundsAssert)));});
