test('Visual V4.5 preserves a valid Save V2 position and sends an out-of-bounds legacy position to that map safe spawn',()=>{const storage=new Persistence.MemoryStorageAdapter(),initial=()=>({currentMapId:'MAP_01',player:FimbriaRuntime.resolveSpawn('MAP_01'),mapRuntime:{},moving:false,moveInterval:null,currentEncounterMobIds:null,pendingReturn:null}),save=Persistence.createSaveSystem({storage,mapDatabase:FimbriaRuntime.mapDatabase,itemDb:ItemData,createInitialPlayerState:Rules.createPlayerState,createInitialWorldState:initial,normalizeMapId:FimbriaRuntime.normalizeMapId});storage.value=JSON.stringify({version:2,player:Rules.createPlayerState(),world:{currentMapId:'MAP_10',player:{x:99,y:99}},progression:{}});let loaded=save.load();assert.equal(loaded.valid,true);assert.equal(loaded.world.currentMapId,'MAP_10');assert.deepEqual(loaded.world.player,FimbriaRuntime.resolveSpawn('MAP_10'));storage.value=JSON.stringify({version:2,player:Rules.createPlayerState(),world:{currentMapId:'MAP_10',player:{x:2,y:3}},progression:{}});loaded=save.load();assert.deepEqual(loaded.world.player,{x:2,y:3});assert.equal(Persistence.SAVE_VERSION,2);});
