// V8-QA: integrated reachability audit for the active runtime map graph.
test('V8-QA every runtime exit, canonical NPC and encounter placement is reachable without crossing blocked cells',()=>{
  const reachable=(map,start)=>{const queue=[start],seen=new Set([`${start.x},${start.y}`]);for(let i=0;i<queue.length;i++){const point=queue[i];for(const next of [{x:point.x+1,y:point.y},{x:point.x-1,y:point.y},{x:point.x,y:point.y+1},{x:point.x,y:point.y-1}]){const key=`${next.x},${next.y}`;if(!seen.has(key)&&FimbriaRuntime.isWalkable(map.id,next)){seen.add(key);queue.push(next);}}}return seen;};
  Object.values(FimbriaRuntime.mapDatabase).forEach(map=>{const cells=reachable(map,FimbriaRuntime.resolveSpawn(map.id));map.exits.forEach(exit=>{assert(cells.has(`${exit.x},${exit.y}`),`${map.id} exit ${exit.id} is unreachable`);const permitted=exit.requiresFlag?FimbriaRuntime.prepareTransition({mapId:map.id,exitId:exit.id,flagProvider:()=>true}):FimbriaRuntime.prepareTransition({mapId:map.id,exitId:exit.id});assert(permitted.ok,`${map.id} exit ${exit.id}: ${permitted.reason}`);assert(FimbriaRuntime.isWalkable(permitted.targetMapId,permitted.targetPosition));});map.mobs.forEach(mob=>assert(cells.has(`${mob.x},${mob.y}`),`${map.id} encounter placement ${mob.id} is unreachable`));});
  Object.values(NpcData).forEach(npc=>{const map=FimbriaRuntime.resolveMap(npc.mapId),cells=reachable(map,FimbriaRuntime.resolveSpawn(map.id));assert(cells.has(`${npc.position.x},${npc.position.y}`),`${npc.id} is unreachable on ${npc.mapId}`);});
  ['MAP_03','MAP_09'].forEach(id=>assert.equal(FimbriaRuntime.resolveMap(id).exits.length,0));
});
