test('V8-QA-FIX A+B MAIN_01 starts at Mira and advances through canonical MAP_VISITED and KILL events',()=>{const f=makeFimbriaRuntimeFixture(),start=f.talk('guarda_mira'),accept=start.dialogue.options.find(o=>o.id==='accept_quest'&&o.questId==='MAIN_01');assert(accept);assert(f.npcs.execute('guarda_mira',accept).ok);assert(f.visit('EXIT_MAP01_MAP02').ok);assert.equal(f.questSystem.getObjectiveViews('MAIN_01').find(o=>o.id==='main01_map02').current,1);f.questSystem.recordEvent(FimbriaRuntime.adaptQuestEvent({type:'MOB_KILLED',mobType:'CRE_CASCUDO_DE_CAL',eventId:'main01-kill'}));assert.equal(f.questSystem.getObjectiveViews('MAIN_01').find(o=>o.id==='main01_cascudo').current,1);assert(f.visit('EXIT_MAP02_MAP01').ok);const ready=f.talk('guarda_mira').dialogue.options.find(o=>o.id==='deliver_quest'&&o.questId==='MAIN_01');assert(ready);assert(f.npcs.execute('guarda_mira',ready).ok);assert.equal(f.questSystem.getQuestState('MAIN_01'),'COMPLETED');assert.equal(f.questSystem.getQuestState('MAIN_02'),'AVAILABLE');});
