test('V8-QA-FIX A+B Save V2 preserves inspection flags, items and canonical quest progress without duplicate reload grants',()=>{const storage=new Persistence.MemoryStorageAdapter(),f=makeFimbriaRuntimeFixture({storage}),point=FimbriaInspections.POINTS[0];f.world.currentMapId=point.mapId;f.world.player=FimbriaRuntime.resolveSpawn(point.mapId);f.questSystem.questDb.collect_tufo_test={id:'collect_tufo_test',canonical:true,prerequisites:[],objectives:[{id:'tufo',type:'COLLECT',target:point.itemId,amount:1}],rewards:{}};assert(f.questSystem.acceptQuest('collect_tufo_test'));assert(f.inspections.inspect(point.id).ok);assert(f.save.saveNow());const loaded=f.save.load();assert.equal(loaded.valid,true);assert.equal(loaded.player.inventory[point.itemId],1);assert.equal(loaded.progression.flags[point.flag],true);assert.equal(loaded.progression.quests.collect_tufo_test.progress.tufo,1);const q=QuestApi.createQuestSystem({questDb:f.questDb,progression:loaded.progression.quests,autoComplete:false,inventoryProvider:()=>loaded.player}),w=WorldApi.createWorldState({progressionProvider:()=>loaded.progression,questSystem:q}),inspections=FimbriaInspections.createInspectionSystem({runtime:FimbriaRuntime,worldState:w,questSystem:q,itemSink:({itemId,amount})=>Rules.addLoot(loaded.player,[{id:itemId,qty:amount}])});assert(inspections.inspect(point.id).duplicate);assert.equal(loaded.player.inventory[point.itemId],1);assert.equal(Persistence.SAVE_VERSION,2);});
