test('V8-QA-FIX A+B MAIN_04 completion alone opens the Marco-Prumo stair through MapGates and persists in Save V2',()=>{const f=makeFimbriaRuntimeFixture();f.progression.quests.MAIN_03={state:'COMPLETED',progress:{},seenEvents:{},rewardClaimed:true};f.questSystem.setProgression(f.progression.quests);assert(f.questSystem.acceptQuest('MAIN_04'));assert.equal(f.gates.destinations('MAP_05',Fimbria.exits).includes('MAP_07'),false);assert.equal(FimbriaRuntime.prepareTransition({mapId:'MAP_05',exitId:'EXIT_ESCADA_MARCO_PRUMO',flagProvider:id=>f.worldState.hasFlag(id)}).reason,'GATE_CLOSED');f.visit('EXIT_CARROCAL');f.visit('EXIT_MAP04_MAP05');f.inspections.inspect('POINT_MARCO_PRUMO_REGISTRO');f.visit('EXIT_MAP05_MAP04');f.visit('EXIT_MAP04_MAP06');f.inspections.inspect('POINT_PONTE_PAGINA_BATIDAS');f.visit('EXIT_MAP06_MAP04');f.visit('EXIT_MAP04_MAP01');f.talk('exploradora_lia');f.questSystem.recordEvent({type:'NPC_TALKED',npcId:'NPC_LIA',eventId:'main04-turnin'});assert(f.questSystem.isComplete('MAIN_04'));assert(f.npcs.execute('exploradora_lia',{id:'deliver_quest',questId:'MAIN_04'}).ok);assert.equal(f.worldState.hasFlag('FLAG_ESCADA_MARCO_PRUMO_UNLOCKED'),true);assert.deepEqual(f.gates.destinations('MAP_05',Fimbria.exits),['MAP_07']);assert(FimbriaRuntime.prepareTransition({mapId:'MAP_05',exitId:'EXIT_ESCADA_MARCO_PRUMO',flagProvider:id=>f.worldState.hasFlag(id)}).ok);const storage=new Persistence.MemoryStorageAdapter(),save=Persistence.createSaveSystem({storage,mapDatabase:FimbriaRuntime.mapDatabase,itemDb:ItemData,createInitialPlayerState:Rules.createPlayerState,createInitialWorldState:()=>({currentMapId:'MAP_01',player:FimbriaRuntime.resolveSpawn('MAP_01'),mapRuntime:{}}),normalizeMapId:FimbriaRuntime.normalizeMapId,stateProvider:()=>({player:f.player,world:f.world,progression:f.progression})});save.saveNow();const loaded=save.load();assert.equal(loaded.progression.flags.FLAG_ESCADA_MARCO_PRUMO_UNLOCKED,true);assert.equal(loaded.progression.quests.MAIN_04.state,'COMPLETED');});
